(361, 80, '_form', '<div class=\"row g-3\">\n<div class=\"col-md-6\">\n<div class=\"acx3-field\">\n<label for=\"acx3Name\" class=\"acx3-label\">Name</label>\n[text* your-name id:acx3Name class:acx3-input placeholder \"Your name\"]\n</div>\n</div>\n<div class=\"col-md-6\">\n<div class=\"acx3-field\">\n<label for=\"acx3Phone\" class=\"acx3-label\">Phone</label>\n[tel* your-phone id:acx3Phone class:acx3-input placeholder \"Your phone number\"]\n</div>\n</div>\n<div class=\"col-md-6\">\n<div class=\"acx3-field\">\n<label for=\"acx3Email\" class=\"acx3-label\">Email</label>\n[email* your-email id:acx3Email class:acx3-input placeholder \"Your email address\"]\n</div>\n</div>\n<div class=\"col-md-6\">\n<div class=\"acx3-field\">\n<label for=\"acx3Interest\" class=\"acx3-label\">Interested In</label>\n[select your-interest id:acx3Interest class:acx3-select first_as_label \"Select an option\" \"Layout / Plot\" \"Custom Home Construction\" \"House / Villa\" \"Loan Assistance\" \"Joint Venture\" \"Other\"]\n</div>\n</div>\n<div class=\"col-12\">\n<div class=\"acx3-field\">\n<label for=\"acx3Message\" class=\"acx3-label\">Message</label>\n[textarea your-message id:acx3Message class:acx3-input class:acx3-textarea placeholder \"Write your requirement...\"]\n</div>\n</div>\n<div class=\"col-12\">\n[submit class:acx3-submit \"Submit Enquiry\"]\n</div>\n</div>'),
(362, 80, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:29:\"Enquiry For \"[your-interest]\"\";s:6:\"sender\";s:36:\"contact form <kulalbalu45@gmail.com>\";s:9:\"recipient\";s:21:\"kulalbalu45@gmail.com\";s:4:\"body\";s:231:\"From: [your-name] [your-email]\nSubject: Enquiry For \"[your-interest]\"\nPhone No: [your-phone]\n\nMessage Body:\n[your-message]\n\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title], [_site_url]).\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}'),
