(19, 1, '2026-10-29 11:27:57', '2026-10-29 11:27:57', '<article>\r\n   <section class=\"abb-about-banner\">\r\n\r\n    <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-about-banner.jpg\"\r\n         class=\"abb-about-banner-image\"\r\n         alt=\"Arun Bhandary Builders & Developers\"\r\n         title=\"Arun Bhandary Builders & Developers\"\r\n         loading=\"eager\">\r\n\r\n    <div class=\"abb-about-banner-overlay\"></div>\r\n\r\n    <div class=\"abb-about-banner-content\">\r\n\r\n        <!-- Breadcrumb -->\r\n        <nav class=\"abb-about-banner-breadcrumb\" aria-label=\"breadcrumb\">\r\n\r\n            <span class=\"abb-about-banner-breadcrumb-line\"></span>\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n\r\n            <span>/</span>\r\n\r\n            <strong>About Us</strong>\r\n\r\n        </nav>\r\n\r\n        <!-- Label -->\r\n        <div class=\"abb-about-banner-label\">\r\n            ABOUT US\r\n        </div>\r\n\r\n        <!-- Heading -->\r\n        <h1 class=\"abb-about-banner-heading\">\r\n            <span>Building Homes.</span>\r\n            <span>Creating Possibilities.</span>\r\n        </h1>\r\n\r\n        <!-- Description -->\r\n        <p class=\"abb-about-banner-description\">\r\n            Thoughtfully planned layouts, customized homes and\r\n            lasting communities across Mangaluru, Udupi and Moodabidire.\r\n        </p>\r\n\r\n        <!-- Red line -->\r\n        <div class=\"abb-about-banner-redline\"></div>\r\n\r\n    </div>\r\n\r\n    <!-- Architectural decoration -->\r\n    <div class=\"abb-about-banner-corner\"></div>\r\n\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     ABOUT US - INTRODUCTION\r\n========================================================= -->\r\n<section class=\"abb-about-intro\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"row align-items-center g-0\">\r\n\r\n            <!-- LEFT IMAGE -->\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"abb-about-intro-image-wrap\">\r\n\r\n                    <div class=\"abb-about-intro-image-frame\"></div>\r\n\r\n                    <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-about1.jpg\"\r\n                         class=\"abb-about-intro-image\"\r\n                         alt=\"Customized home by Arun Bhandary Builders & Developers\"\r\n                         title=\"Arun Bhandary Builders & Developers\"\r\n                         loading=\"lazy\">\r\n\r\n                    <!-- Image label -->\r\n                    <div class=\"abb-about-intro-image-label\">\r\n                        <!-- <span class=\"abb-about-intro-image-label-number\">\r\n                            01\r\n                        </span> -->\r\n\r\n                        <span>\r\n                            OUR APPROACH\r\n                        </span>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RIGHT CONTENT -->\r\n            <div class=\"col-lg-6\">\r\n\r\n               <div class=\"abb-about-intro-content\">\r\n\r\n    <div class=\"abb-about-intro-company\">\r\n        ARUN BHANDARY BUILDERS &amp; DEVELOPERS\r\n    </div>\r\n\r\n    <div class=\"abb-about-section-label\">\r\n        <span></span>\r\n        WHO WE ARE\r\n    </div>\r\n\r\n    <h2 class=\"abb-about-intro-heading\">\r\n        Every Home\r\n        <strong>Begins With A Vision.</strong>\r\n    </h2>\r\n\r\n    <div class=\"abb-about-intro-divider\">\r\n        <span></span>\r\n    </div>\r\n\r\n    <p>\r\n        <strong>Arun Bhandary Builders &amp; Developers</strong>\r\n        helps you turn your vision of a home into reality. Your dream\r\n        home begins with the right choice of location, layout and\r\n        design. We offer thoughtfully planned layouts and plots,\r\n        along with customized house construction tailored to your\r\n        requirements and budget.\r\n    </p>\r\n\r\n    <p>\r\n        With guidance on planning, construction and loan assistance,\r\n        we support you at every stage—from selecting your plot and\r\n        designing your home to bringing it to completion across\r\n        <strong>Mangaluru, Udupi and Moodabidire.</strong>\r\n    </p>\r\n\r\n    <div class=\"abb-about-intro-highlight\">\r\n\r\n        <div class=\"abb-about-intro-highlight-icon\">\r\n            <i class=\"fa-solid fa-house\"></i>\r\n        </div>\r\n\r\n        <div>\r\n            <span>YOUR PLOT</span>\r\n            <strong>YOUR HOME</strong>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n<!-- =========================================================\r\n     ABOUT US - DESIGN OPTION 2\r\n========================================================= -->\r\n<section class=\"abb-about-story-v2\">\r\n\r\n  \r\n\r\n    <div class=\"abb-about-story-v2-line\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n\r\n            <!-- =============================================\r\n                 LEFT CONTENT\r\n            ============================================== -->\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"abb-about-story-v2-content\">\r\n\r\n                    <div class=\"abb-about-story-v2-label\">\r\n                        <span class=\"abb-about-story-v2-label-line\"></span>\r\n                        OUR STORY\r\n                    </div>\r\n\r\n                    <h2 class=\"abb-about-story-v2-heading\">\r\n                        Creating Spaces\r\n                        <span>Made For Living.</span>\r\n                    </h2>\r\n\r\n                    <p class=\"abb-about-story-v2-lead\">\r\n                        At Arun Bhandary Builders &amp; Developers,\r\n                        we believe a home is more than a structure.\r\n                        It is a space shaped around the way you live,\r\n                        your aspirations and the people who matter to you.\r\n                    </p>\r\n\r\n                    <p class=\"abb-about-story-v2-text\">\r\n                        From thoughtfully planned layouts and plots to\r\n                        customized house construction, we bring together\r\n                        planning, design and construction to help create\r\n                        homes that are practical, personal and enduring.\r\n                    </p>\r\n\r\n\r\n                    <!-- Small information row -->\r\n\r\n                    <div class=\"abb-about-story-v2-info\">\r\n\r\n                        <div class=\"abb-about-story-v2-info-item\">\r\n\r\n                            <strong>\r\n                                01\r\n                            </strong>\r\n\r\n                            <div>\r\n                                <span>PLAN</span>\r\n                                <small>\r\n                                    Thoughtful beginnings\r\n                                </small>\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"abb-about-story-v2-info-item\">\r\n\r\n                            <strong>\r\n                                02\r\n                            </strong>\r\n\r\n                            <div>\r\n                                <span>DESIGN</span>\r\n                                <small>\r\n                                    Made around you\r\n                                </small>\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"abb-about-story-v2-info-item\">\r\n\r\n                            <strong>\r\n                                03\r\n                            </strong>\r\n\r\n                            <div>\r\n                                <span>BUILD</span>\r\n                                <small>\r\n                                    Built with care\r\n                                </small>\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- =============================================\r\n                 RIGHT IMAGE\r\n            ============================================== -->\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"abb-about-story-v2-visual\">\r\n\r\n                    <!-- Decorative red block -->\r\n                    <div class=\"abb-about-story-v2-red-block\"></div>\r\n\r\n                    <!-- Image frame -->\r\n                    <div class=\"abb-about-story-v2-frame\"></div>\r\n\r\n                    <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-about2.jpg\"\r\n                         class=\"abb-about-story-v2-image\"\r\n                         alt=\"Customized home by Arun Bhandary Builders & Developers\"\r\n                         title=\"Arun Bhandary Builders & Developers\"\r\n                         loading=\"lazy\">\r\n\r\n\r\n                    <!-- Image tag -->\r\n\r\n                    <div class=\"abb-about-story-v2-tag\">\r\n\r\n                        <span>\r\n                            ARUN BHANDARY\r\n                        </span>\r\n\r\n                        <strong>\r\n                            BUILDERS &amp; DEVELOPERS\r\n                        </strong>\r\n\r\n                    </div>\r\n\r\n\r\n                    <!-- Corner mark -->\r\n\r\n                    <div class=\"abb-about-story-v2-corner\">\r\n\r\n                        <span></span>\r\n                        <span></span>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =========================================================\r\n     ABOUT US - LAYOUT & PLOTS\r\n========================================================= -->\r\n<section class=\"abb-about-layout-v3\">\r\n\r\n    <!-- Subtle architectural background -->\r\n    <div class=\"abb-about-layout-v3-bg\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <!-- =================================================\r\n             HEADING\r\n        ================================================== -->\r\n        <div class=\"row align-items-lg-end align-items-center\">\r\n\r\n            <div class=\"col-lg-8\">\r\n\r\n                <div class=\"abb-about-layout-v3-label\">\r\n                    <span></span>\r\n                    LAYOUTS &amp; PLOTS\r\n                </div>\r\n\r\n                <h2 class=\"abb-about-layout-v3-heading\">\r\n                    The Beginning Of\r\n                    <span>Something Truly Yours.</span>\r\n                </h2>\r\n\r\n            </div>\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <p class=\"abb-about-layout-v3-intro\">\r\n                    The journey towards your dream home starts\r\n                    with choosing the right place. Thoughtfully\r\n                    planned layouts and carefully considered plots\r\n                    provide the foundation for what comes next.\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =================================================\r\n             MAIN ARCHITECTURAL SECTION\r\n        ================================================== -->\r\n        <div class=\"abb-about-layout-v3-main\">\r\n\r\n            <div class=\"row g-0\">\r\n\r\n\r\n                <!-- =========================================\r\n                     LEFT CONTENT\r\n                ========================================== -->\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"abb-about-layout-v3-side\">\r\n\r\n                        <div class=\"abb-about-layout-v3-small-title\">\r\n                            CHOOSE YOUR PLACE\r\n                        </div>\r\n\r\n                        <h3>\r\n                            Find The Right\r\n                            <span>Plot.</span>\r\n                        </h3>\r\n\r\n                        <p>\r\n                            Explore thoughtfully planned layouts\r\n                            and choose a location that suits your\r\n                            requirements, lifestyle and future plans.\r\n                        </p>\r\n\r\n                        <div class=\"abb-about-layout-v3-side-accent\"></div>\r\n\r\n                        <div class=\"abb-about-layout-v3-side-bottom\">\r\n                            <i class=\"fa-solid fa-location-dot\"></i>\r\n                            <span>LOCATION • LAYOUT • POSSIBILITY</span>\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n\r\n                <!-- =========================================\r\n                     CENTRAL ARCHITECTURAL PLAN\r\n                ========================================== -->\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"abb-about-layout-v3-plan\">\r\n\r\n                        <div class=\"abb-about-layout-v3-plan-heading\">\r\n\r\n                            <span>RESIDENTIAL</span>\r\n\r\n                            <strong>MASTER PLAN</strong>\r\n\r\n                        </div>\r\n\r\n\r\n                        <!-- Plot diagram -->\r\n                        <div class=\"abb-about-layout-v3-plots\">\r\n\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n                            <div class=\"abb-about-layout-v3-plot abb-about-layout-v3-selected\"></div>\r\n\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n                            <div class=\"abb-about-layout-v3-plot\"></div>\r\n\r\n                        </div>\r\n\r\n\r\n                        <!-- Roads -->\r\n                        <div class=\"abb-about-layout-v3-road abb-road-horizontal\">\r\n                            <span></span>\r\n                        </div>\r\n\r\n                        <div class=\"abb-about-layout-v3-road abb-road-vertical\">\r\n                            <span></span>\r\n                        </div>\r\n\r\n\r\n                        <!-- Compass -->\r\n                        <div class=\"abb-about-layout-v3-compass\">\r\n\r\n                            <span>N</span>\r\n\r\n                            <i></i>\r\n\r\n                        </div>\r\n\r\n\r\n                        <!-- Selected plot indicator -->\r\n                        <div class=\"abb-about-layout-v3-selected-label\">\r\n\r\n                            <span>YOUR</span>\r\n\r\n                            <strong>SPACE</strong>\r\n\r\n                        </div>\r\n\r\n\r\n                        <!-- Corner architectural lines -->\r\n                        <div class=\"abb-about-layout-v3-corner corner-top\"></div>\r\n\r\n                        <div class=\"abb-about-layout-v3-corner corner-bottom\"></div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n\r\n                <!-- =========================================\r\n                     RIGHT CONTENT\r\n                ========================================== -->\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"abb-about-layout-v3-side abb-about-layout-v3-side-right\">\r\n\r\n                        <div class=\"abb-about-layout-v3-small-title\">\r\n                            SHAPE YOUR FUTURE\r\n                        </div>\r\n\r\n                        <h3>\r\n                            Build A Home\r\n                            <span>That Is Yours.</span>\r\n                        </h3>\r\n\r\n                        <p>\r\n                            Your chosen plot becomes the starting\r\n                            point for a home designed around your\r\n                            needs, preferences and budget.\r\n                        </p>\r\n\r\n                        <div class=\"abb-about-layout-v3-side-accent\"></div>\r\n\r\n                        <div class=\"abb-about-layout-v3-side-bottom\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                            <span>DESIGN • BUILD • LIVE</span>\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =================================================\r\n             BOTTOM STATEMENT\r\n        ================================================== -->\r\n        <div class=\"abb-about-layout-v3-bottom\">\r\n\r\n            <div class=\"abb-about-layout-v3-bottom-line\"></div>\r\n\r\n            <div class=\"abb-about-layout-v3-bottom-content\">\r\n\r\n                <small>\r\n                    FROM PLOT TO POSSIBILITY\r\n                </small>\r\n\r\n                <strong>\r\n                    YOUR HOME JOURNEY, PLANNED AROUND YOU.\r\n                </strong>\r\n\r\n            </div>\r\n\r\n            <div class=\"abb-about-layout-v3-bottom-arrow\">\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n<!-- JOINT VENTURE SECTION -->\r\n<section class=\"abb-jv3-section\">\r\n\r\n    <div class=\"abb-jv3-bg-shape abb-jv3-bg-shape-1\"></div>\r\n    <div class=\"abb-jv3-bg-shape abb-jv3-bg-shape-2\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <!-- TOP -->\r\n        <div class=\"abb-jv3-top\">\r\n            <div class=\"abb-jv3-kicker\">\r\n                <span class=\"abb-jv3-kicker-line\"></span>\r\n                <span>JOINT VENTURE</span>\r\n            </div>\r\n\r\n            <div class=\"abb-jv3-top-word\">\r\n                PARTNERSHIP\r\n            </div>\r\n        </div>\r\n\r\n\r\n        <!-- MAIN CONTENT -->\r\n        <div class=\"abb-jv3-main\">\r\n\r\n            <!-- LEFT -->\r\n            <div class=\"abb-jv3-intro\">\r\n\r\n                <div class=\"abb-jv3-small-title\">\r\n                    HAVE LAND?\r\n                </div>\r\n\r\n                <h2 class=\"abb-jv3-heading\">\r\n                    Let\'s Turn\r\n                    <span>Land Into</span>\r\n                    Something\r\n                    <strong>Meaningful.</strong>\r\n                </h2>\r\n\r\n                <div class=\"abb-jv3-heading-line\">\r\n                    <span></span>\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RIGHT -->\r\n            <div class=\"abb-jv3-content\">\r\n\r\n                <p class=\"abb-jv3-lead\">\r\n                    We offer Joint Venture opportunities for landowners,\r\n                    bringing together land and our expertise in planning,\r\n                    design and construction to develop thoughtfully planned\r\n                    residential projects with quality and lasting value.\r\n                </p>\r\n\r\n                <p class=\"abb-jv3-description\">\r\n                    Your land brings the opportunity. Our experience brings\r\n                    the planning, design and construction expertise required\r\n                    to shape it into a well-planned residential development.\r\n                </p>\r\n\r\n\r\n                <!-- PROCESS -->\r\n                <div class=\"abb-jv3-process\">\r\n\r\n                    <div class=\"abb-jv3-process-item\">\r\n                        <div class=\"abb-jv3-process-mark\"></div>\r\n                        <div>\r\n                            <span>YOUR LAND</span>\r\n                            <p>A valuable foundation</p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"abb-jv3-process-connector\"></div>\r\n\r\n                    <div class=\"abb-jv3-process-item\">\r\n                        <div class=\"abb-jv3-process-mark\"></div>\r\n                        <div>\r\n                            <span>OUR EXPERTISE</span>\r\n                            <p>Planning &amp; construction</p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"abb-jv3-process-connector\"></div>\r\n\r\n                    <div class=\"abb-jv3-process-item\">\r\n                        <div class=\"abb-jv3-process-mark\"></div>\r\n                        <div>\r\n                            <span>NEW POSSIBILITIES</span>\r\n                            <p>Thoughtfully developed spaces</p>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n\r\n                <!-- CTA -->\r\n                <div class=\"abb-jv3-action\">\r\n\r\n                    <a href=\"http://localhost/arun-bhandary-builders/contact-us\" class=\"abb-jv3-button\">\r\n                        <span>DISCUSS YOUR LAND</span>\r\n                        <i class=\"fa-solid fa-arrow-right\"></i>\r\n                    </a>\r\n\r\n                    <div class=\"abb-jv3-action-note\">\r\n                        <span class=\"abb-jv3-action-dot\"></span>\r\n                        <span>LET\'S EXPLORE THE POSSIBILITY</span>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- BOTTOM STATEMENT -->\r\n        <div class=\"abb-jv3-bottom\">\r\n\r\n            <div class=\"abb-jv3-bottom-line\"></div>\r\n\r\n            <div class=\"abb-jv3-bottom-text\">\r\n                <span>LAND</span>\r\n                <i></i>\r\n                <span>VISION</span>\r\n                <i></i>\r\n                <strong>DEVELOPMENT</strong>\r\n            </div>\r\n\r\n            <div class=\"abb-jv3-bottom-line\"></div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- VISION & MISSION — OPTION 5 -->\r\n<section class=\"abb-vm5-section\">\r\n\r\n    <div class=\"abb-vm5-grid-lines\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <!-- TOP -->\r\n        <div class=\"abb-vm5-top\">\r\n            <div class=\"abb-vm5-eyebrow\">\r\n                <span class=\"abb-vm5-eyebrow-line\"></span>\r\n                OUR VISION &amp; MISSION\r\n            </div>\r\n\r\n            <div class=\"abb-vm5-top-note\">\r\n                <span>ARUN BHANDARY</span>\r\n                <span>BUILDERS &amp; DEVELOPERS</span>\r\n            </div>\r\n        </div>\r\n\r\n\r\n        <!-- MAIN -->\r\n        <div class=\"abb-vm5-main\">\r\n\r\n            <!-- LEFT BIG WORD -->\r\n            <div class=\"abb-vm5-word-wrap\">\r\n                <div class=\"abb-vm5-word\">VISION</div>\r\n\r\n                <div class=\"abb-vm5-vertical-line\"></div>\r\n\r\n                <div class=\"abb-vm5-side-text\">\r\n                    LOOKING AHEAD\r\n                </div>\r\n            </div>\r\n\r\n\r\n            <!-- VISION CONTENT -->\r\n            <div class=\"abb-vm5-content abb-vm5-content-vision\">\r\n\r\n                <div class=\"abb-vm5-content-label\">\r\n                    OUR VISION\r\n                </div>\r\n\r\n                <h2>\r\n                    Better places.\r\n                    <span>Better living.</span>\r\n                </h2>\r\n\r\n                <p>\r\n                    To create thoughtfully planned residential spaces and\r\n                    customized homes that bring together quality, comfort,\r\n                    practical design and lasting value for families across\r\n                    Mangaluru, Udupi and Moodabidire.\r\n                </p>\r\n\r\n                <div class=\"abb-vm5-content-line\">\r\n                    <span></span>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- MISSION -->\r\n        <div class=\"abb-vm5-main abb-vm5-main-mission\">\r\n\r\n            <div class=\"abb-vm5-content abb-vm5-content-mission\">\r\n\r\n                <div class=\"abb-vm5-content-label\">\r\n                    OUR MISSION\r\n                </div>\r\n\r\n                <h2>\r\n                    Built around\r\n                    <span>your journey.</span>\r\n                </h2>\r\n\r\n                <p>\r\n                    To guide every customer through the journey from selecting\r\n                    the right plot and planning the home to construction and\r\n                    completion, with transparent guidance, dependable execution\r\n                    and a commitment to quality at every stage.\r\n                </p>\r\n\r\n                <div class=\"abb-vm5-content-line\">\r\n                    <span></span>\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RIGHT BIG WORD -->\r\n            <div class=\"abb-vm5-word-wrap abb-vm5-word-wrap-right\">\r\n\r\n                <div class=\"abb-vm5-word\">MISSION</div>\r\n\r\n                <div class=\"abb-vm5-vertical-line\"></div>\r\n\r\n                <div class=\"abb-vm5-side-text\">\r\n                    OUR APPROACH\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- BOTTOM STATEMENT -->\r\n       <!-- BOTTOM STATEMENT -->\r\n<div class=\"abb-vm5-bottom\">\r\n\r\n    <div class=\"abb-vm5-bottom-rule\">\r\n        <span></span>\r\n    </div>\r\n\r\n    <div class=\"abb-vm5-bottom-text\">\r\n        <span>THE IDEA IS SIMPLE</span>\r\n\r\n        <strong>\r\n            Create spaces where people\r\n            can build a life of their own.\r\n        </strong>\r\n    </div>\r\n\r\n    <div class=\"abb-vm5-bottom-location\">\r\n        <span>MANGALURU</span>\r\n        <i></i>\r\n        <span>UDUPI</span>\r\n        <i></i>\r\n        <span>MOODABIDIRE</span>\r\n    </div>\r\n\r\n</div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =========================================================\r\n     ABOUT PAGE CTA — OPTION 2\r\n========================================================= -->\r\n\r\n<section class=\"abb-about-cta2\">\r\n\r\n    <div class=\"abb-about-cta2-top-line\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-about-cta2-inner\">\r\n\r\n            <!-- LEFT CONTENT -->\r\n            <div class=\"abb-about-cta2-content\">\r\n\r\n                <div class=\"abb-about-cta2-label\">\r\n                    <span></span>\r\n                    YOUR HOME JOURNEY\r\n                </div>\r\n\r\n                <h2>\r\n                    It all starts\r\n                    <span>with a place.</span>\r\n                </h2>\r\n\r\n                <p>\r\n                    Choose the right plot. Shape the right plan.\r\n                    Build a home that feels truly yours.\r\n                </p>\r\n\r\n                <a href=\"http://localhost/arun-bhandary-builders/contact-us\" class=\"abb-about-cta2-button\">\r\n                    <span>LET\'S TALK ABOUT YOUR HOME</span>\r\n                    <i class=\"fa-solid fa-arrow-right\"></i>\r\n                </a>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RIGHT VISUAL -->\r\n            <div class=\"abb-about-cta2-visual\">\r\n\r\n                <div class=\"abb-about-cta2-red-panel\">\r\n\r\n                    <div class=\"abb-about-cta2-red-top\">\r\n                        <span>ARUN BHANDARY</span>\r\n                        <span>BUILDERS &amp; DEVELOPERS</span>\r\n                    </div>\r\n\r\n                    <div class=\"abb-about-cta2-red-center\">\r\n\r\n                        <div class=\"abb-about-cta2-word\">\r\n                            HOME\r\n                        </div>\r\n\r\n                        <div class=\"abb-about-cta2-line\"></div>\r\n\r\n                        <div class=\"abb-about-cta2-caption\">\r\n                            <span>DESIGN</span>\r\n                            <span>BUILD</span>\r\n                            <span>LIVE</span>\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                    <div class=\"abb-about-cta2-red-bottom\">\r\n                        MANGALURU · UDUPI · MOODABIDIRE\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <!-- <div class=\"abb-about-cta2-outline-text\">\r\n                    BEGIN\r\n                </div> -->\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- BOTTOM STRIP -->\r\n        <div class=\"abb-about-cta2-bottom\">\r\n\r\n            <span>\r\n                CUSTOMIZED HOME CONSTRUCTION\r\n            </span>\r\n\r\n            <div class=\"abb-about-cta2-bottom-rule\"></div>\r\n\r\n            <a href=\"tel:+918904819565\">\r\n                +91 8904 819 565\r\n            </a>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n</article>', 'Overview', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-10-29 11:27:57', '2026-10-29 11:27:57', '', 16, 'http://localhost/arun-bhandary-builders/?p=19', 0, 'revision', '', 0),
