(23, 1, '2026-10-29 11:33:02', '2026-10-29 11:33:02', '<article>\r\n    <!-- =========================================================\r\n     MANAGING DIRECTOR MESSAGE\r\n     ARUN BHANDARY BUILDERS & DEVELOPERS\r\n     ========================================================= -->\r\n\r\n<section class=\"abb-md9-section\">\r\n\r\n    <!-- Decorative architectural lines -->\r\n    <div class=\"abb-md9-grid-line abb-md9-grid-line-1\"></div>\r\n    <div class=\"abb-md9-grid-line abb-md9-grid-line-2\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <!-- =====================================================\r\n             PAGE INTRO\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-intro\">\r\n\r\n            <div class=\"abb-md9-intro-left\">\r\n\r\n                <div class=\"abb-md9-eyebrow\">\r\n                    <span></span>\r\n                    MESSAGE FROM THE MANAGING DIRECTOR\r\n                </div>\r\n\r\n                <h1>\r\n                    Building\r\n                    <span>with purpose.</span>\r\n                </h1>\r\n\r\n            </div>\r\n\r\n            <div class=\"abb-md9-intro-right\">\r\n\r\n                <p>\r\n                    A home is more than a structure. It is a reflection\r\n                    of the people, aspirations and life that grow within it.\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             MAIN MD AREA\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-main\">\r\n\r\n            <!-- PHOTO -->\r\n            <div class=\"abb-md9-photo-area\">\r\n\r\n                <div class=\"abb-md9-photo-frame\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-md.jpg\"\r\n                        alt=\"Arun Bhandary - Managing Director\"\r\n                        title=\"Arun Bhandary - Managing Director\"\r\n                        class=\"abb-md9-photo\"\r\n                    >\r\n\r\n                    <div class=\"abb-md9-photo-tag\">\r\n\r\n                        <strong>\r\n                            Arun Bhandary\r\n                        </strong>\r\n\r\n                        <span>\r\n                            Managing Director\r\n                        </span>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- CONTENT -->\r\n            <div class=\"abb-md9-content\">\r\n\r\n                <div class=\"abb-md9-content-label\">\r\n                    OUR APPROACH\r\n                </div>\r\n\r\n                <h2>\r\n                    Every home\r\n                    <span>begins with a vision.</span>\r\n                </h2>\r\n\r\n                <p class=\"abb-md9-lead\">\r\n\r\n                    Your dream home begins with the right choice of\r\n                    location, layout and design.\r\n\r\n                </p>\r\n\r\n                <p>\r\n\r\n                    At Arun Bhandary Builders &amp; Developers,\r\n                    we understand that building a home is an important\r\n                    decision for every family. It begins with finding\r\n                    the right place and continues through planning,\r\n                    designing and constructing a home that fits the\r\n                    way you want to live.\r\n\r\n                </p>\r\n\r\n                <p>\r\n\r\n                    We offer thoughtfully planned layouts and plots,\r\n                    along with customized house construction tailored\r\n                    to your requirements and budget. Our approach is\r\n                    focused on giving customers the freedom to create\r\n                    a home that feels personal, practical and comfortable.\r\n\r\n                </p>\r\n\r\n\r\n                <!-- PROCESS LINE -->\r\n\r\n                <div class=\"abb-md9-process\">\r\n\r\n                    <div>\r\n                        <strong>PLAN</strong>\r\n                        <span>Start with the right place.</span>\r\n                    </div>\r\n\r\n                    <div>\r\n                        <strong>DESIGN</strong>\r\n                        <span>Shape the home around you.</span>\r\n                    </div>\r\n\r\n                    <div>\r\n                        <strong>BUILD</strong>\r\n                        <span>Bring the vision to life.</span>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             FEATURE QUOTE\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-quote\">\r\n\r\n            <div class=\"abb-md9-quote-mark\">\r\n                “\r\n            </div>\r\n\r\n            <div class=\"abb-md9-quote-content\">\r\n\r\n                <div class=\"abb-md9-quote-label\">\r\n                    A SIMPLE BELIEF\r\n                </div>\r\n\r\n                <h2>\r\n                    Your home should be\r\n                    <span>built around your life.</span>\r\n                </h2>\r\n\r\n                <p>\r\n\r\n                    Every family has its own priorities, routines and\r\n                    aspirations. That is why we believe a home should\r\n                    not simply be constructed—it should be thoughtfully\r\n                    planned around the people who will call it their own.\r\n\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             MESSAGE BLOCK\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-message\">\r\n\r\n            <div class=\"abb-md9-message-heading\">\r\n\r\n                <span></span>\r\n\r\n                FROM PLOT TO HOME\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-md9-message-content\">\r\n\r\n                <div class=\"abb-md9-message-column\">\r\n\r\n                    <h3>\r\n                        The right beginning\r\n                        matters.\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Choosing a suitable plot and location creates\r\n                        the foundation for everything that follows.\r\n                        We help customers look at the possibilities\r\n                        of their chosen location and layout so that\r\n                        the future home can be planned with greater\r\n                        clarity.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-md9-message-column\">\r\n\r\n                    <h3>\r\n                        Designed for\r\n                        real life.\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        From the arrangement of spaces to the details\r\n                        that make everyday living comfortable, our\r\n                        customized construction approach allows the\r\n                        home to respond to individual requirements,\r\n                        lifestyle and budget.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-md9-message-column\">\r\n\r\n                    <h3>\r\n                        Guided throughout\r\n                        the journey.\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        With guidance on planning, construction and\r\n                        loan assistance, we support customers through\r\n                        the different stages of turning an initial\r\n                        idea into a completed home.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             LOCATION STATEMENT\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-location\">\r\n\r\n            <div class=\"abb-md9-location-left\">\r\n\r\n                <span>\r\n                    WHERE WE BUILD\r\n                </span>\r\n\r\n                <h2>\r\n                    Creating possibilities\r\n                    <span>across the region.</spn>\r\n                </h2>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-md9-location-right\">\r\n\r\n                <p>\r\n\r\n                    Our work spans across Mangaluru, Udupi and\r\n                    Moodabidire, supporting families who are looking\r\n                    for the right combination of location, planning,\r\n                    design and construction.\r\n\r\n                </p>\r\n\r\n\r\n                <div class=\"abb-md9-location-list\">\r\n\r\n                    <strong>MANGALURU</strong>\r\n\r\n                    <i></i>\r\n\r\n                    <strong>UDUPI</strong>\r\n\r\n                    <i></i>\r\n\r\n                    <strong>MOODABIDIRE</strong>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             MEMBERSHIPS\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-memberships\">\r\n\r\n            <div class=\"abb-md9-membership-title\">\r\n\r\n                <span></span>\r\n\r\n                MEMBERSHIPS &amp; ASSOCIATIONS\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-md9-membership-list\">\r\n\r\n                <div class=\"abb-md9-member\">\r\n                    <strong>Rotary</strong>\r\n                </div>\r\n\r\n                <div class=\"abb-md9-member\">\r\n                    <strong>RMBF</strong>\r\n                </div>\r\n\r\n                <div class=\"abb-md9-member\">\r\n                    <strong>KBA</strong>\r\n                </div>\r\n\r\n                <div class=\"abb-md9-member\">\r\n                    <strong>KCCI</strong>\r\n                </div>\r\n\r\n                <div class=\"abb-md9-member\">\r\n                    <strong>MYWROOM</strong>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             CLOSING MESSAGE\r\n             ===================================================== -->\r\n\r\n        <div class=\"abb-md9-closing\">\r\n\r\n            <div class=\"abb-md9-closing-main\">\r\n\r\n                <div class=\"abb-md9-closing-label\">\r\n                    BUILDING WITH PURPOSE\r\n                </div>\r\n\r\n                <h2>\r\n                    From choosing a place\r\n                    <span>to creating a home.</span>\r\n                </h2>\r\n\r\n                <p>\r\n\r\n                    Our commitment is to make that journey clearer,\r\n                    more thoughtful and more personal—helping every\r\n                    customer move from an idea to a home that truly\r\n                    belongs to them.\r\n\r\n                </p>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-md9-signature\">\r\n\r\n                <div class=\"abb-md9-signature-name\">\r\n                    Arun Bhandary\r\n                </div>\r\n\r\n                <div class=\"abb-md9-signature-line\"></div>\r\n\r\n                <strong>\r\n                    MANAGING DIRECTOR\r\n                </strong>\r\n\r\n                <span>\r\n                    Arun Bhandary Builders &amp; Developers Pvt. Ltd.\r\n                </span>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- =====================================================\r\n             BOTTOM BRAND STRIP\r\n             ===================================================== -->\r\n\r\n    \r\n\r\n    </div>\r\n\r\n</section>\r\n</article>', 'MD Message', '', 'inherit', 'closed', 'closed', '', '22-revision-v1', '', '', '2026-10-29 11:33:02', '2026-10-29 11:33:02', '', 22, 'http://localhost/arun-bhandary-builders/?p=23', 0, 'revision', '', 0),
