(56, 1, '2026-10-30 11:29:21', '2026-10-30 11:29:21', '<article>\r\n    <!-- =========================================================\r\n     HERO\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-hero\">\r\n\r\n    <div class=\"abb-rc5-hero-grid\"></div>\r\n\r\n    <div class=\"abb-rc5-hero-red-shape\"></div>\r\n\r\n    <div class=\"abb-rc5-hero-side-label\">\r\n        ARUN BHANDARY BUILDERS &amp; DEVELOPERS\r\n    </div>\r\n\r\n\r\n    <div class=\"container abb-rc5-hero-content\">\r\n\r\n        <!-- Breadcrumb -->\r\n\r\n        <div class=\"abb-rc5-breadcrumb\">\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/\">\r\n                Home\r\n            </a>\r\n\r\n            <i class=\"fa-solid fa-chevron-right\"></i>\r\n\r\n            <span>\r\n                Residential Construction\r\n            </span>\r\n\r\n        </div>\r\n\r\n\r\n        <!-- Label -->\r\n\r\n        <div class=\"abb-rc5-hero-label\">\r\n            RESIDENTIAL CONSTRUCTION\r\n        </div>\r\n\r\n\r\n        <!-- Heading -->\r\n\r\n        <h1 class=\"abb-rc5-hero-title\">\r\n\r\n            Build A Home\r\n\r\n            <span>That Is Yours.</span>\r\n\r\n        </h1>\r\n\r\n\r\n        <!-- Description -->\r\n\r\n        <p class=\"abb-rc5-hero-description\">\r\n\r\n            Your chosen plot is where the journey begins.\r\n            We help you turn that place into a thoughtfully\r\n            planned and customized home shaped around your\r\n            requirements, lifestyle and budget.\r\n\r\n        </p>\r\n\r\n\r\n        <!-- Button -->\r\n\r\n        <a href=\"#contact\"\r\n           class=\"abb-rc5-hero-button\">\r\n\r\n            START YOUR HOME JOURNEY\r\n\r\n            <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n        </a>\r\n\r\n    </div>\r\n\r\n\r\n    <!-- Hero image -->\r\n\r\n    <div class=\"abb-rc5-hero-image\">\r\n\r\n        <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-residential-construction-hero.jpg\"\r\n             alt=\"Modern customized residential house\">\r\n\r\n        <div class=\"abb-rc5-image-caption\">\r\n            CUSTOM HOME CONSTRUCTION\r\n        </div>\r\n\r\n    </div>\r\n\r\n\r\n    <!-- Bottom info -->\r\n\r\n    <div class=\"abb-rc5-hero-bottom\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <div class=\"abb-rc5-hero-bottom-inner\">\r\n\r\n                <div class=\"abb-rc5-hero-bottom-item\">\r\n\r\n                    <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                    MANGALURU\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-hero-bottom-item\">\r\n\r\n                    <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                    UDUPI\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-hero-bottom-item\">\r\n\r\n                    <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                    MOODABIDIRE\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-hero-bottom-item\">\r\n\r\n                    <i class=\"fa-solid fa-phone\"></i>\r\n\r\n                    +91 8904 819 565\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     INTRO\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-intro\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-intro-label\">\r\n            THE WAY WE SEE IT\r\n        </div>\r\n\r\n\r\n        <h2 class=\"abb-rc5-intro-title\">\r\n\r\n            A home is not a standard plan.\r\n\r\n            <span>\r\n                It is a reflection of the people who live in it.\r\n            </span>\r\n\r\n        </h2>\r\n\r\n\r\n        <div class=\"abb-rc5-intro-bottom\">\r\n\r\n            <div class=\"abb-rc5-intro-rule\"></div>\r\n\r\n            <p class=\"abb-rc5-intro-text\">\r\n\r\n                Every family has different needs.\r\n                That is why our residential construction\r\n                approach begins with understanding how\r\n                you want to live.\r\n\r\n                From the layout of your rooms to the\r\n                way your spaces connect, we help create\r\n                a home that works for your everyday life.\r\n\r\n            </p>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     ARCHITECTURE\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-architecture\">\r\n\r\n    <div class=\"abb-rc5-architecture-grid\"></div>\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-architecture-heading\">\r\n\r\n            <div class=\"abb-rc5-small-label\">\r\n\r\n                <span></span>\r\n\r\n                DESIGN &amp; PLANNING\r\n\r\n            </div>\r\n\r\n\r\n            <h2 class=\"abb-rc5-architecture-title\">\r\n\r\n                Good construction begins\r\n                with good thinking.\r\n\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"abb-rc5-architecture-visual\">\r\n\r\n\r\n            <div class=\"abb-rc5-architecture-image\">\r\n\r\n                <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-residential-construction-home.jpg\"\r\n                     alt=\"Residential home designed and constructed by Arun Bhandary Builders\">\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-rc5-architecture-panel\">\r\n\r\n                <div class=\"abb-rc5-architecture-panel-label\">\r\n\r\n                    YOUR REQUIREMENTS\r\n\r\n                </div>\r\n\r\n\r\n                <h3>\r\n\r\n                    Planned around\r\n                    <span>your life.</span>\r\n\r\n                </h3>\r\n\r\n\r\n                <p>\r\n\r\n                    We consider the character of your plot,\r\n                    your family requirements, preferred spaces,\r\n                    practical needs and budget before moving\r\n                    into construction.\r\n\r\n                </p>\r\n\r\n\r\n                <p class=\"mt-4\">\r\n\r\n                    The result is a home that is not simply\r\n                    constructed on your plot, but thoughtfully\r\n                    shaped for the way you intend to live.\r\n\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     SERVICES\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-services\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"abb-rc5-services-header\">\r\n\r\n            <div>\r\n\r\n                <div class=\"abb-rc5-small-label\">\r\n\r\n                    <span></span>\r\n\r\n                    OUR SERVICES\r\n\r\n                </div>\r\n\r\n\r\n                <h2 class=\"abb-rc5-services-title\">\r\n\r\n                    From idea to\r\n                    <span>completion.</span>\r\n\r\n                </h2>\r\n\r\n            </div>\r\n\r\n\r\n            <p class=\"abb-rc5-services-description\">\r\n\r\n                We bring together the key stages of your\r\n                home journey so that planning, design and\r\n                construction work together seamlessly.\r\n\r\n            </p>\r\n\r\n        </div>\r\n\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <!-- Service -->\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-service\">\r\n\r\n                    <div class=\"abb-rc5-service-icon\">\r\n\r\n                        <i class=\"fa-solid fa-ruler-combined\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3>\r\n                        Planning\r\n                    </h3>\r\n\r\n\r\n                    <p>\r\n\r\n                        Understand the plot and your\r\n                        requirements to establish a practical\r\n                        direction for your home.\r\n\r\n                    </p>\r\n\r\n\r\n                   \r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <!-- Service -->\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-service\">\r\n\r\n                    <div class=\"abb-rc5-service-icon\">\r\n\r\n                        <i class=\"fa-solid fa-pen-ruler\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3>\r\n                        Design\r\n                    </h3>\r\n\r\n\r\n                    <p>\r\n\r\n                        Shape your home around the spaces,\r\n                        functionality and style that matter\r\n                        to your family.\r\n\r\n                    </p>\r\n\r\n\r\n                    \r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <!-- Service -->\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-service\">\r\n\r\n                    <div class=\"abb-rc5-service-icon\">\r\n\r\n                        <i class=\"fa-solid fa-helmet-safety\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3>\r\n                        Construction\r\n                    </h3>\r\n\r\n\r\n                    <p>\r\n\r\n                        Execute the project with attention\r\n                        to workmanship, materials and\r\n                        finishing.\r\n\r\n                    </p>\r\n\r\n\r\n                    \r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <!-- Service -->\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-service\">\r\n\r\n                    <div class=\"abb-rc5-service-icon\">\r\n\r\n                        <i class=\"fa-solid fa-handshake\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3>\r\n                        Guidance\r\n                    </h3>\r\n\r\n\r\n                    <p>\r\n\r\n                        Receive support throughout the\r\n                        journey, including planning,\r\n                        construction and loan assistance.\r\n\r\n                    </p>\r\n\r\n\r\n                   \r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CUSTOMIZATION\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-custom\">\r\n\r\n    <div class=\"abb-rc5-custom-word\">\r\n        HOME\r\n    </div>\r\n\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-custom-content\">\r\n\r\n\r\n            <div class=\"abb-rc5-small-label\">\r\n\r\n                <span></span>\r\n\r\n                CUSTOMIZED CONSTRUCTION\r\n\r\n            </div>\r\n\r\n\r\n            <h2 class=\"abb-rc5-custom-title\">\r\n\r\n                Your home should work\r\n                <span>for you.</span>\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"abb-rc5-custom-description\">\r\n\r\n                Whether it is the number of bedrooms,\r\n                living spaces, kitchen planning, parking\r\n                requirements or outdoor areas, your home\r\n                can be shaped around the way your family\r\n                actually lives.\r\n\r\n            </p>\r\n\r\n\r\n            <div class=\"abb-rc5-custom-list\">\r\n\r\n\r\n                <div class=\"abb-rc5-custom-item\">\r\n\r\n                    <i class=\"fa-solid fa-check\"></i>\r\n\r\n                    Bedrooms &amp; private spaces\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-custom-item\">\r\n\r\n                    <i class=\"fa-solid fa-check\"></i>\r\n\r\n                    Living &amp; dining areas\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-custom-item\">\r\n\r\n                    <i class=\"fa-solid fa-check\"></i>\r\n\r\n                    Kitchen planning\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-custom-item\">\r\n\r\n                    <i class=\"fa-solid fa-check\"></i>\r\n\r\n                    Parking requirements\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-custom-item\">\r\n\r\n                    <i class=\"fa-solid fa-check\"></i>\r\n\r\n                    Outdoor spaces\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"abb-rc5-custom-item\">\r\n\r\n                    <i class=\"fa-solid fa-check\"></i>\r\n\r\n                    Finishing preferences\r\n\r\n                </div>\r\n\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     PROCESS\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-process\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"abb-rc5-small-label\">\r\n\r\n            <span></span>\r\n\r\n            OUR APPROACH\r\n\r\n        </div>\r\n\r\n\r\n        <h2 class=\"abb-rc5-process-title\">\r\n\r\n            A clear journey from\r\n            <span>plot to home.</span>\r\n\r\n        </h2>\r\n\r\n\r\n        <p class=\"abb-rc5-process-intro\">\r\n\r\n            Building your home should feel like a guided\r\n            journey, not a complicated process. We work\r\n            through each stage with you so that decisions\r\n            are clear and the construction stays focused\r\n            on the final vision.\r\n\r\n        </p>\r\n\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-process-item\">\r\n\r\n                    <div class=\"abb-rc5-process-item-label\">\r\n                        YOUR PLOT\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Start With The Right Place\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Begin with your chosen plot,\r\n                        location and layout.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-process-item\">\r\n\r\n                    <div class=\"abb-rc5-process-item-label\">\r\n                        YOUR PLAN\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Shape The Spaces\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Plan the home around your\r\n                        family\'s needs and lifestyle.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-process-item\">\r\n\r\n                    <div class=\"abb-rc5-process-item-label\">\r\n                        YOUR BUILD\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Construct With Care\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Bring the design to life through\r\n                        focused construction.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-process-item\">\r\n\r\n                    <div class=\"abb-rc5-process-item-label\">\r\n                        YOUR HOME\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Make It Truly Yours\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Complete a home designed\r\n                        around the way you live.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     LOCATIONS\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-location\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"abb-rc5-location-heading\">\r\n\r\n            <div class=\"abb-rc5-small-label\">\r\n\r\n                <span></span>\r\n\r\n                WHERE WE BUILD\r\n\r\n            </div>\r\n\r\n\r\n            <h2 class=\"abb-rc5-location-title\">\r\n\r\n                Homes across\r\n                <span>the region.</span>\r\n\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"abb-rc5-location-item\">\r\n\r\n                    <h3>\r\n                        Mangaluru\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Customized residential construction\r\n                        across Mangaluru and surrounding areas.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"abb-rc5-location-item\">\r\n\r\n                    <h3>\r\n                        Udupi\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Thoughtfully planned homes and\r\n                        residential construction across Udupi.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"abb-rc5-location-item\">\r\n\r\n                    <h3>\r\n                        Moodabidire\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Helping families transform their\r\n                        chosen plots into customized homes.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CTA\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-cta\"\r\n         id=\"contact\">\r\n\r\n    <div class=\"abb-rc5-cta-grid\"></div>\r\n\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-cta-content\">\r\n\r\n\r\n            <div class=\"abb-rc5-cta-label\">\r\n\r\n                LET\'S BUILD YOUR HOME\r\n\r\n            </div>\r\n\r\n\r\n            <h2 class=\"abb-rc5-cta-title\">\r\n\r\n                You choose the place.\r\n\r\n                <span>\r\n                    We help create the home.\r\n                </span>\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"abb-rc5-cta-text\">\r\n\r\n                Tell us about your plot, your requirements\r\n                and the home you have in mind. Let\'s discuss\r\n                how we can take your idea forward.\r\n\r\n            </p>\r\n\r\n\r\n            <a href=\"tel:+918904819565\"\r\n               class=\"abb-rc5-cta-button\">\r\n\r\n                TALK TO US\r\n\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n            </a>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     BOTTOM\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-bottom\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-bottom-inner\">\r\n\r\n\r\n            <div class=\"abb-rc5-bottom-brand\">\r\n\r\n                ARUN BHANDARY BUILDERS &amp; DEVELOPERS\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-rc5-bottom-locations\">\r\n\r\n                MANGALURU\r\n\r\n                <i class=\"fa-solid fa-circle\"></i>\r\n\r\n                UDUPI\r\n\r\n                <i class=\"fa-solid fa-circle\"></i>\r\n\r\n                MOODABIDIRE\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n</article>', 'Residential Construction', '', 'publish', 'closed', 'closed', '', 'residential-construction', '', '', '2026-10-30 11:33:19', '2026-10-30 11:33:19', '', 0, 'http://localhost/arun-bhandary-builders/?page_id=56', 0, 'page', '', 0);
