          </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-3 col-md-6\">\r\n\r\n                <div class=\"abb-rc5-process-item\">\r\n\r\n                    <div class=\"abb-rc5-process-item-label\">\r\n                        YOUR HOME\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Make It Truly Yours\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Complete a home designed\r\n                        around the way you live.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     LOCATIONS\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-location\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"abb-rc5-location-heading\">\r\n\r\n            <div class=\"abb-rc5-small-label\">\r\n\r\n                <span></span>\r\n\r\n                WHERE WE BUILD\r\n\r\n            </div>\r\n\r\n\r\n            <h2 class=\"abb-rc5-location-title\">\r\n\r\n                Homes across\r\n                <span>the region.</span>\r\n\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"abb-rc5-location-item\">\r\n\r\n                    <h3>\r\n                        Mangaluru\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Customized residential construction\r\n                        across Mangaluru and surrounding areas.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"abb-rc5-location-item\">\r\n\r\n                    <h3>\r\n                        Udupi\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Thoughtfully planned homes and\r\n                        residential construction across Udupi.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"abb-rc5-location-item\">\r\n\r\n                    <h3>\r\n                        Moodabidire\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Helping families transform their\r\n                        chosen plots into customized homes.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CTA\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-cta\"\r\n         id=\"contact\">\r\n\r\n    <div class=\"abb-rc5-cta-grid\"></div>\r\n\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-cta-content\">\r\n\r\n\r\n            <div class=\"abb-rc5-cta-label\">\r\n\r\n                LET\'S BUILD YOUR HOME\r\n\r\n            </div>\r\n\r\n\r\n            <h2 class=\"abb-rc5-cta-title\">\r\n\r\n                You choose the place.\r\n\r\n                <span>\r\n                    We help create the home.\r\n                </span>\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"abb-rc5-cta-text\">\r\n\r\n                Tell us about your plot, your requirements\r\n                and the home you have in mind. Let\'s discuss\r\n                how we can take your idea forward.\r\n\r\n            </p>\r\n\r\n\r\n            <a href=\"tel:+918904819565\"\r\n               class=\"abb-rc5-cta-button\">\r\n\r\n                TALK TO US\r\n\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n            </a>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     BOTTOM\r\n========================================================= -->\r\n\r\n<section class=\"abb-rc5-bottom\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"abb-rc5-bottom-inner\">\r\n\r\n\r\n            <div class=\"abb-rc5-bottom-brand\">\r\n\r\n                ARUN BHANDARY BUILDERS &amp; DEVELOPERS\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abb-rc5-bottom-locations\">\r\n\r\n                MANGALURU\r\n\r\n                <i class=\"fa-solid fa-circle\"></i>\r\n\r\n                UDUPI\r\n\r\n                <i class=\"fa-solid fa-circle\"></i>\r\n\r\n                MOODABIDIRE\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n</article>', 'Residential Construction', '', 'inherit', 'closed', 'closed', '', '56-revision-v1', '', '', '2026-10-30 11:33:19', '2026-10-30 11:33:19', '', 56, 'http://localhost/arun-bhandary-builders/?p=58', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(59, 1, '2026-10-30 11:39:47', '2026-10-30 11:39:47', '<article>\r\n    \r\n    \r\n<!-- =========================================================\r\n     HERO\r\n========================================================= -->\r\n\r\n<section class=\"ald-hero\">\r\n\r\n\r\n    <!-- BREADCRUMB INSIDE HERO -->\r\n\r\n    <div class=\"ald-breadcrumb-wrap\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <nav aria-label=\"breadcrumb\">\r\n\r\n                <ul class=\"ald-breadcrumb\">\r\n\r\n                    <li>\r\n                        <a href=\"http://localhost/arun-bhandary-builders/\">\r\n                            Home\r\n                        </a>\r\n                    </li>\r\n\r\n                    <li class=\"ald-breadcrumb-arrow\">\r\n                        <i class=\"fa-solid fa-chevron-right\"></i>\r\n                    </li>\r\n\r\n                    <li>\r\n                        <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">\r\n                            Services\r\n                        </a>\r\n                    </li>\r\n\r\n                    <li class=\"ald-breadcrumb-arrow\">\r\n                        <i class=\"fa-solid fa-chevron-right\"></i>\r\n                    </li>\r\n\r\n                    <li class=\"ald-current\">\r\n                        Layout Development\r\n                    </li>\r\n\r\n                </ul>\r\n\r\n            </nav>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n\r\n    <!-- HERO CONTENT -->\r\n\r\n    <div class=\"container ald-hero-content\">\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n            <!-- LEFT CONTENT -->\r\n\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"ald-hero-copy\">\r\n\r\n                    <div class=\"ald-eyebrow\">\r\n                        Layout Development\r\n                    </div>\r\n\r\n\r\n                    <h1 class=\"ald-hero-title\">\r\n\r\n                        Planned For<br>\r\n\r\n                        <span>Better Living.</span>\r\n\r\n                    </h1>\r\n\r\n\r\n                    <p class=\"ald-hero-description\">\r\n\r\n                        Thoughtfully planned residential layouts that\r\n                        bring together well-defined plots, practical\r\n                        road networks, open spaces and a setting where\r\n                        families can build homes with confidence.\r\n\r\n                    </p>\r\n\r\n\r\n                    <a href=\"#ald-enquiry\"\r\n                       class=\"ald-hero-button\">\r\n\r\n                        Explore Our Approach\r\n\r\n                        <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n                    </a>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RIGHT HERO IMAGE -->\r\n            <!-- NORMAL IMG - NOT A BACKGROUND -->\r\n\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"ald-hero-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-layout-development-hero.jpg\"\r\n                        alt=\"Residential layout development\"\r\n                        loading=\"eager\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     INTRO\r\n========================================================= -->\r\n\r\n<section class=\"ald-intro\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-intro-label\">\r\n            Thoughtful Planning\r\n        </div>\r\n\r\n\r\n        <h2 class=\"ald-intro-title\">\r\n\r\n            A good layout is more than a collection of plots.\r\n\r\n            <span>\r\n                It is the beginning of a community.\r\n            </span>\r\n\r\n        </h2>\r\n\r\n\r\n        <p class=\"ald-intro-text\">\r\n\r\n            Our layout development approach focuses on creating\r\n            residential environments that are practical, accessible\r\n            and thoughtfully planned. From the arrangement of plots\r\n            and internal roads to open areas, landscaping and overall\r\n            connectivity, every element is considered with future\r\n            homeowners in mind.\r\n\r\n        </p>\r\n\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     IMAGE STORY\r\n========================================================= -->\r\n\r\n<section class=\"ald-story\">\r\n\r\n    <div class=\"container-fluid px-lg-0\">\r\n\r\n        <div class=\"row g-0 align-items-stretch\">\r\n\r\n\r\n            <!-- IMAGE -->\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ald-story-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-layout-development-aerial.jpg\"\r\n                        alt=\"Planned residential layout development\"\r\n                        loading=\"lazy\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- CONTENT -->\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ald-story-content\">\r\n\r\n\r\n                    <div class=\"ald-story-small\">\r\n                        Designed Around The Land\r\n                    </div>\r\n\r\n\r\n                    <h2 class=\"ald-story-title\">\r\n\r\n                        From land to a well-planned neighbourhood.\r\n\r\n                    </h2>\r\n\r\n\r\n                    <p class=\"ald-story-text\">\r\n\r\n                        We study the land, its surroundings and its\r\n                        potential before shaping the layout. The result\r\n                        is a planned environment where individual plots\r\n                        connect naturally with roads, landscape and\r\n                        shared spaces.\r\n\r\n                    </p>\r\n\r\n\r\n                    <ul class=\"ald-story-list\">\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Carefully planned residential plots\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Practical internal road planning\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Landscaped open spaces\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Thoughtful access and connectivity\r\n                        </li>\r\n\r\n                    </ul>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     PLANNING FEATURES\r\n========================================================= -->\r\n\r\n<section class=\"ald-planning\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-section-heading\">\r\n\r\n\r\n            <div class=\"ald-section-label\">\r\n                What We Consider\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-section-title\">\r\n\r\n                Every part of the layout has a\r\n                <span>purpose.</span>\r\n\r\n            </h2>\r\n\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <!-- PLOT -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-map\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Plot Planning\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Plot sizes and positioning are considered\r\n                        to create practical opportunities for future\r\n                        home construction.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- ROAD -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-road\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Road Network\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Internal roads are planned to provide\r\n                        convenient movement and straightforward\r\n                        access to residential plots.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- OPEN SPACE -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-tree\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Open Spaces\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Green areas and thoughtfully positioned\r\n                        open spaces help create a more pleasant\r\n                        residential environment.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- CONNECTIVITY -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Connectivity\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Location and surrounding connectivity are\r\n                        considered to make each development\r\n                        convenient for everyday living.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     LARGE IMAGE\r\n========================================================= -->\r\n\r\n<section class=\"ald-landscape\">\r\n\r\n\r\n    <div class=\"ald-landscape-image\">\r\n\r\n        <img\r\n            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-layout-development-road.jpg\"\r\n            alt=\"Residential layout road and landscaped development\"\r\n            loading=\"lazy\"\r\n        >\r\n\r\n    </div>\r\n\r\n\r\n    <div class=\"ald-landscape-overlay\"></div>\r\n\r\n\r\n    <div class=\"container ald-landscape-content\">\r\n\r\n        <div class=\"ald-landscape-copy\">\r\n\r\n\r\n            <div class=\"ald-landscape-label\">\r\n                Built For Tomorrow\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-landscape-title\">\r\n\r\n                A place where your future home\r\n                can take shape.\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"ald-landscape-text\">\r\n\r\n                A thoughtfully developed layout gives homeowners\r\n                the freedom to choose their plot and later create\r\n                a home around their own lifestyle, needs and\r\n                aspirations.\r\n\r\n            </p>\r\n\r\n\r\n            <div class=\"ald-landscape-points\">\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Residential Plots\r\n                </span>\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Planned Roads\r\n                </span>\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Green Spaces\r\n                </span>\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Future-Ready Planning\r\n                </span>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     DEVELOPMENT APPROACH\r\n========================================================= -->\r\n\r\n<section class=\"ald-process\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-process-intro\">\r\n\r\n\r\n            <div class=\"ald-section-label\">\r\n                Our Approach\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-process-heading\">\r\n\r\n                From understanding the land to creating\r\n                a place\r\n\r\n                <span>\r\n                    worth building on.\r\n                </span>\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"ald-process-description\">\r\n\r\n                Layout development requires careful coordination\r\n                between land characteristics, planning, access,\r\n                infrastructure and the needs of future homeowners.\r\n                We approach every development with attention to\r\n                both the present site and its future potential.\r\n\r\n            </p>\r\n\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ald-process-card\">\r\n\r\n                    <i class=\"fa-solid fa-compass-drafting\"></i>\r\n\r\n                    <h3>\r\n                        Understand The Site\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        We consider the character of the land,\r\n                        surrounding development, access and the\r\n                        opportunities offered by the location.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ald-process-card\">\r\n\r\n                    <i class=\"fa-solid fa-draw-polygon\"></i>\r\n\r\n                    <h3>\r\n                        Shape The Layout\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Plot arrangements, roads, access points,\r\n                        open spaces and the overall movement through\r\n                        the development are planned together.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ald-process-card\">\r\n\r\n                    <i class=\"fa-solid fa-house-chimney\"></i>\r\n\r\n                    <h3>\r\n                        Create Future Possibilities\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        The finished layout gives families a\r\n                        considered place where they can select\r\n                        their plot and build a home suited to\r\n                        their own way of living.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     BENEFITS\r\n========================================================= -->\r\n\r\n<section class=\"ald-benefits\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-section-label\"\r\n             style=\"color:#f07a80;\">\r\n\r\n            Why Planned Layouts Matter\r\n\r\n        </div>\r\n\r\n\r\n        <h2 class=\"ald-benefits-title\">\r\n\r\n            The right planning creates\r\n\r\n            <span>\r\n                lasting value.\r\n            </span>\r\n\r\n        </h2>\r\n\r\n\r\n        <p class=\"ald-benefits-description\">\r\n\r\n            A well-planned residential development creates\r\n            a stronger foundation for individual homes and\r\n            the community around them. Good planning today\r\n            can make everyday living more comfortable tomorrow.\r\n\r\n        </p>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-house\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Better Home Potential\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Plots are planned to offer practical\r\n                        opportunities for creating comfortable homes.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-arrows-left-right\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Easier Movement\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Thoughtful road planning supports convenient\r\n                        access throughout the development.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-leaf\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Greener Surroundings\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Landscape and open areas contribute to a\r\n                        more comfortable residential setting.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-location-crosshairs\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Considered Locations\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Location and surrounding connectivity remain\r\n                        central to the planning of each development.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CTA\r\n========================================================= -->\r\n\r\n<section class=\"ald-cta\"\r\n         id=\"ald-enquiry\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-cta-inner\">\r\n\r\n\r\n            <div class=\"ald-cta-label\">\r\n                Find Your Place\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-cta-title\">\r\n\r\n                Choose the right plot.\r\n                Build the home that feels like yours.\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"ald-cta-text\">\r\n\r\n                Explore our thoughtfully planned layouts and\r\n                discover opportunities to create a home around\r\n                your lifestyle, requirements and future plans.\r\n\r\n            </p>\r\n\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/all-projects/\"\r\n               class=\"ald-cta-button\">\r\n\r\n                Explore Our Projects\r\n\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n            </a>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n</article>', 'Layout Development', '', 'publish', 'closed', 'closed', '', 'layout-development', '', '', '2026-10-30 11:39:47', '2026-10-30 11:39:47', '', 0, 'http://localhost/arun-bhandary-builders/?page_id=59', 0, 'page', '', 0),
(60, 1, '2026-10-30 11:39:47', '2026-10-30 11:39:47', '<article>\r\n    \r\n    \r\n<!-- =========================================================\r\n     HERO\r\n========================================================= -->\r\n\r\n<section class=\"ald-hero\">\r\n\r\n\r\n    <!-- BREADCRUMB INSIDE HERO -->\r\n\r\n    <div class=\"ald-breadcrumb-wrap\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <nav aria-label=\"breadcrumb\">\r\n\r\n                <ul class=\"ald-breadcrumb\">\r\n\r\n                    <li>\r\n                        <a href=\"http://localhost/arun-bhandary-builders/\">\r\n                            Home\r\n                        </a>\r\n                    </li>\r\n\r\n                    <li class=\"ald-breadcrumb-arrow\">\r\n                        <i class=\"fa-solid fa-chevron-right\"></i>\r\n                    </li>\r\n\r\n                    <li>\r\n                        <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">\r\n                            Services\r\n                        </a>\r\n                    </li>\r\n\r\n                    <li class=\"ald-breadcrumb-arrow\">\r\n                        <i class=\"fa-solid fa-chevron-right\"></i>\r\n                    </li>\r\n\r\n                    <li class=\"ald-current\">\r\n                        Layout Development\r\n                    </li>\r\n\r\n                </ul>\r\n\r\n            </nav>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n\r\n    <!-- HERO CONTENT -->\r\n\r\n    <div class=\"container ald-hero-content\">\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n            <!-- LEFT CONTENT -->\r\n\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"ald-hero-copy\">\r\n\r\n                    <div class=\"ald-eyebrow\">\r\n                        Layout Development\r\n                    </div>\r\n\r\n\r\n                    <h1 class=\"ald-hero-title\">\r\n\r\n                        Planned For<br>\r\n\r\n                        <span>Better Living.</span>\r\n\r\n                    </h1>\r\n\r\n\r\n                    <p class=\"ald-hero-description\">\r\n\r\n                        Thoughtfully planned residential layouts that\r\n                        bring together well-defined plots, practical\r\n                        road networks, open spaces and a setting where\r\n                        families can build homes with confidence.\r\n\r\n                    </p>\r\n\r\n\r\n                    <a href=\"#ald-enquiry\"\r\n                       class=\"ald-hero-button\">\r\n\r\n                        Explore Our Approach\r\n\r\n                        <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n                    </a>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RIGHT HERO IMAGE -->\r\n            <!-- NORMAL IMG - NOT A BACKGROUND -->\r\n\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"ald-hero-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-layout-development-hero.jpg\"\r\n                        alt=\"Residential layout development\"\r\n                        loading=\"eager\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     INTRO\r\n========================================================= -->\r\n\r\n<section class=\"ald-intro\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-intro-label\">\r\n            Thoughtful Planning\r\n        </div>\r\n\r\n\r\n        <h2 class=\"ald-intro-title\">\r\n\r\n            A good layout is more than a collection of plots.\r\n\r\n            <span>\r\n                It is the beginning of a community.\r\n            </span>\r\n\r\n        </h2>\r\n\r\n\r\n        <p class=\"ald-intro-text\">\r\n\r\n            Our layout development approach focuses on creating\r\n            residential environments that are practical, accessible\r\n            and thoughtfully planned. From the arrangement of plots\r\n            and internal roads to open areas, landscaping and overall\r\n            connectivity, every element is considered with future\r\n            homeowners in mind.\r\n\r\n        </p>\r\n\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     IMAGE STORY\r\n========================================================= -->\r\n\r\n<section class=\"ald-story\">\r\n\r\n    <div class=\"container-fluid px-lg-0\">\r\n\r\n        <div class=\"row g-0 align-items-stretch\">\r\n\r\n\r\n            <!-- IMAGE -->\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ald-story-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-layout-development-aerial.jpg\"\r\n                        alt=\"Planned residential layout development\"\r\n                        loading=\"lazy\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- CONTENT -->\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ald-story-content\">\r\n\r\n\r\n                    <div class=\"ald-story-small\">\r\n                        Designed Around The Land\r\n                    </div>\r\n\r\n\r\n                    <h2 class=\"ald-story-title\">\r\n\r\n                        From land to a well-planned neighbourhood.\r\n\r\n                    </h2>\r\n\r\n\r\n                    <p class=\"ald-story-text\">\r\n\r\n                        We study the land, its surroundings and its\r\n                        potential before shaping the layout. The result\r\n                        is a planned environment where individual plots\r\n                        connect naturally with roads, landscape and\r\n                        shared spaces.\r\n\r\n                    </p>\r\n\r\n\r\n                    <ul class=\"ald-story-list\">\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Carefully planned residential plots\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Practical internal road planning\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Landscaped open spaces\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Thoughtful access and connectivity\r\n                        </li>\r\n\r\n                    </ul>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     PLANNING FEATURES\r\n========================================================= -->\r\n\r\n<section class=\"ald-planning\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-section-heading\">\r\n\r\n\r\n            <div class=\"ald-section-label\">\r\n                What We Consider\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-section-title\">\r\n\r\n                Every part of the layout has a\r\n                <span>purpose.</span>\r\n\r\n            </h2>\r\n\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <!-- PLOT -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-map\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Plot Planning\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Plot sizes and positioning are considered\r\n                        to create practical opportunities for future\r\n                        home construction.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- ROAD -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-road\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Road Network\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Internal roads are planned to provide\r\n                        convenient movement and straightforward\r\n                        access to residential plots.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- OPEN SPACE -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-tree\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Open Spaces\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Green areas and thoughtfully positioned\r\n                        open spaces help create a more pleasant\r\n                        residential environment.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- CONNECTIVITY -->\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-planning-item\">\r\n\r\n\r\n                    <div class=\"ald-planning-icon\">\r\n\r\n                        <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                    </div>\r\n\r\n\r\n                    <h3 class=\"ald-planning-title\">\r\n                        Connectivity\r\n                    </h3>\r\n\r\n\r\n                    <p class=\"ald-planning-text\">\r\n\r\n                        Location and surrounding connectivity are\r\n                        considered to make each development\r\n                        convenient for everyday living.\r\n\r\n                    </p>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     LARGE IMAGE\r\n========================================================= -->\r\n\r\n<section class=\"ald-landscape\">\r\n\r\n\r\n    <div class=\"ald-landscape-image\">\r\n\r\n        <img\r\n            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-layout-development-road.jpg\"\r\n            alt=\"Residential layout road and landscaped development\"\r\n            loading=\"lazy\"\r\n        >\r\n\r\n    </div>\r\n\r\n\r\n    <div class=\"ald-landscape-overlay\"></div>\r\n\r\n\r\n    <div class=\"container ald-landscape-content\">\r\n\r\n        <div class=\"ald-landscape-copy\">\r\n\r\n\r\n            <div class=\"ald-landscape-label\">\r\n                Built For Tomorrow\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-landscape-title\">\r\n\r\n                A place where your future home\r\n                can take shape.\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"ald-landscape-text\">\r\n\r\n                A thoughtfully developed layout gives homeowners\r\n                the freedom to choose their plot and later create\r\n                a home around their own lifestyle, needs and\r\n                aspirations.\r\n\r\n            </p>\r\n\r\n\r\n            <div class=\"ald-landscape-points\">\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Residential Plots\r\n                </span>\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Planned Roads\r\n                </span>\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Green Spaces\r\n                </span>\r\n\r\n                <span class=\"ald-landscape-point\">\r\n                    Future-Ready Planning\r\n                </span>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     DEVELOPMENT APPROACH\r\n========================================================= -->\r\n\r\n<section class=\"ald-process\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-process-intro\">\r\n\r\n\r\n            <div class=\"ald-section-label\">\r\n                Our Approach\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-process-heading\">\r\n\r\n                From understanding the land to creating\r\n                a place\r\n\r\n                <span>\r\n                    worth building on.\r\n                </span>\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"ald-process-description\">\r\n\r\n                Layout development requires careful coordination\r\n                between land characteristics, planning, access,\r\n                infrastructure and the needs of future homeowners.\r\n                We approach every development with attention to\r\n                both the present site and its future potential.\r\n\r\n            </p>\r\n\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-4\">\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ald-process-card\">\r\n\r\n                    <i class=\"fa-solid fa-compass-drafting\"></i>\r\n\r\n                    <h3>\r\n                        Understand The Site\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        We consider the character of the land,\r\n                        surrounding development, access and the\r\n                        opportunities offered by the location.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ald-process-card\">\r\n\r\n                    <i class=\"fa-solid fa-draw-polygon\"></i>\r\n\r\n                    <h3>\r\n                        Shape The Layout\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Plot arrangements, roads, access points,\r\n                        open spaces and the overall movement through\r\n                        the development are planned together.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ald-process-card\">\r\n\r\n                    <i class=\"fa-solid fa-house-chimney\"></i>\r\n\r\n                    <h3>\r\n                        Create Future Possibilities\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        The finished layout gives families a\r\n                        considered place where they can select\r\n                        their plot and build a home suited to\r\n                        their own way of living.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     BENEFITS\r\n========================================================= -->\r\n\r\n<section class=\"ald-benefits\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-section-label\"\r\n             style=\"color:#f07a80;\">\r\n\r\n            Why Planned Layouts Matter\r\n\r\n        </div>\r\n\r\n\r\n        <h2 class=\"ald-benefits-title\">\r\n\r\n            The right planning creates\r\n\r\n            <span>\r\n                lasting value.\r\n            </span>\r\n\r\n        </h2>\r\n\r\n\r\n        <p class=\"ald-benefits-description\">\r\n\r\n            A well-planned residential development creates\r\n            a stronger foundation for individual homes and\r\n            the community around them. Good planning today\r\n            can make everyday living more comfortable tomorrow.\r\n\r\n        </p>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-house\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Better Home Potential\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Plots are planned to offer practical\r\n                        opportunities for creating comfortable homes.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-arrows-left-right\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Easier Movement\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Thoughtful road planning supports convenient\r\n                        access throughout the development.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-leaf\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Greener Surroundings\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Landscape and open areas contribute to a\r\n                        more comfortable residential setting.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-md-6 col-lg-3\">\r\n\r\n                <div class=\"ald-benefit\">\r\n\r\n                    <div class=\"ald-benefit-icon\">\r\n                        <i class=\"fa-solid fa-location-crosshairs\"></i>\r\n                    </div>\r\n\r\n                    <h3>\r\n                        Considered Locations\r\n                    </h3>\r\n\r\n                    <p>\r\n\r\n                        Location and surrounding connectivity remain\r\n                        central to the planning of each development.\r\n\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CTA\r\n========================================================= -->\r\n\r\n<section class=\"ald-cta\"\r\n         id=\"ald-enquiry\">\r\n\r\n    <div class=\"container\">\r\n\r\n\r\n        <div class=\"ald-cta-inner\">\r\n\r\n\r\n            <div class=\"ald-cta-label\">\r\n                Find Your Place\r\n            </div>\r\n\r\n\r\n            <h2 class=\"ald-cta-title\">\r\n\r\n                Choose the right plot.\r\n                Build the home that feels like yours.\r\n\r\n            </h2>\r\n\r\n\r\n            <p class=\"ald-cta-text\">\r\n\r\n                Explore our thoughtfully planned layouts and\r\n                discover opportunities to create a home around\r\n                your lifestyle, requirements and future plans.\r\n\r\n            </p>\r\n\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/all-projects/\"\r\n               class=\"ald-cta-button\">\r\n\r\n                Explore Our Projects\r\n\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n\r\n            </a>\r\n\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n</article>', 'Layout Development', '', 'inherit', 'closed', 'closed', '', '59-revision-v1', '', '', '2026-10-30 11:39:47', '2026-10-30 11:39:47', '', 59, 'http://localhost/arun-bhandary-builders/?p=60', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(61, 1, '2026-10-30 11:43:36', '2026-10-30 11:43:36', '<article>\r\n    \r\n\r\n<!-- =========================================================\r\n     HERO\r\n========================================================= -->\r\n\r\n<section class=\"aad-hero\">\r\n\r\n    <!-- Breadcrumb inside Hero -->\r\n    <div class=\"aad-breadcrumb-wrap\">\r\n        <div class=\"container\">\r\n            <nav aria-label=\"breadcrumb\">\r\n                <ol class=\"breadcrumb aad-breadcrumb\">\r\n                    <li class=\"breadcrumb-item\">\r\n                        <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n                    </li>\r\n\r\n                    <li class=\"breadcrumb-item\">\r\n                        <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">Services</a>\r\n                    </li>\r\n\r\n                    <li class=\"breadcrumb-item active\" aria-current=\"page\">\r\n                        Architectural &amp; Design\r\n                    </li>\r\n                </ol>\r\n            </nav>\r\n        </div>\r\n    </div>\r\n\r\n\r\n    <div class=\"container\">\r\n        <div class=\"row align-items-center aad-hero-main\">\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"aad-hero-content\">\r\n\r\n                    <div class=\"aad-hero-kicker\">\r\n                        <span class=\"aad-hero-kicker-line\"></span>\r\n                        Architectural &amp; Design\r\n                    </div>\r\n\r\n                    <h1 class=\"aad-hero-title\">\r\n                        Spaces\r\n                        <span>With Purpose.</span>\r\n                    </h1>\r\n\r\n                    <p class=\"aad-hero-description\">\r\n                        Thoughtful architecture brings together the way you live,\r\n                        the character of the site and the possibilities of design\r\n                        to create spaces that feel naturally yours.\r\n                    </p>\r\n\r\n                    <div class=\"aad-hero-actions\">\r\n\r\n                        <a href=\"#design\" class=\"aad-hero-button\">\r\n                            Explore Our Approach\r\n                            <i class=\"fa-solid fa-arrow-down\"></i>\r\n                        </a>\r\n\r\n                        <a href=\"#contact\" class=\"aad-hero-link\">\r\n                            Discuss Your Project\r\n                        </a>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"aad-hero-image-wrap\">\r\n\r\n                    <div class=\"aad-hero-image\">\r\n\r\n                        <img\r\n                            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images//arun-bhandary-builders-architectural-design-hero.jpg\"\r\n                            alt=\"Architectural design of a contemporary home\"\r\n                            loading=\"eager\"\r\n                        >\r\n\r\n                        <div class=\"aad-hero-image-label\">\r\n                            <small>Design Approach</small>\r\n                            <strong>Form + Function</strong>\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     INTRO\r\n========================================================= -->\r\n\r\n<section class=\"aad-intro\" id=\"design\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-intro-label\">\r\n            <span class=\"aad-intro-label-line\"></span>\r\n            The Design Perspective\r\n        </div>\r\n\r\n        <h2 class=\"aad-intro-title\">\r\n            Architecture that feels\r\n            <span>personal.</span>\r\n        </h2>\r\n\r\n        <p class=\"aad-intro-text\">\r\n            A well-designed home is more than an attractive elevation.\r\n            It is about understanding the site, natural light, movement,\r\n            privacy, proportions and the everyday routines of the people\r\n            who will live there.\r\n        </p>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     IMAGE STORY\r\n========================================================= -->\r\n\r\n<section class=\"aad-story\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"row g-0 align-items-stretch\">\r\n\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"aad-story-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images//arun-bhandary-builders-architectural-design-home.jpg\"\r\n                        alt=\"Contemporary residential architectural design\"\r\n                        loading=\"lazy\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"aad-story-side\">\r\n\r\n                    <div class=\"aad-story-side-label\">\r\n                        Beyond The Elevation\r\n                    </div>\r\n\r\n                    <h2 class=\"aad-story-side-title\">\r\n                        Designed around\r\n                        <span style=\"color: var(--aad-red);\">\r\n                            your life.\r\n                        </span>\r\n                    </h2>\r\n\r\n                    <p class=\"aad-story-side-text\">\r\n                        From the first concept to the final details,\r\n                        our design approach considers how every space\r\n                        connects with the next.\r\n                    </p>\r\n\r\n                    <p class=\"aad-story-side-text\">\r\n                        The result is a home that balances aesthetics,\r\n                        comfort, functionality and long-term value.\r\n                    </p>\r\n\r\n                    <div class=\"aad-story-note\">\r\n                        Thoughtful planning. Meaningful spaces.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     PHILOSOPHY\r\n========================================================= -->\r\n\r\n<section class=\"aad-philosophy\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-philosophy-label\">\r\n            Our Design Philosophy\r\n        </div>\r\n\r\n        <h2 class=\"aad-philosophy-title\">\r\n            Good architecture\r\n            should look beautiful,\r\n            <span>feel natural</span>\r\n            and work effortlessly.\r\n        </h2>\r\n\r\n        <p class=\"aad-philosophy-description\">\r\n            Every design decision has a purpose. We look beyond trends\r\n            to create homes that remain comfortable, relevant and\r\n            visually balanced over time.\r\n        </p>\r\n\r\n\r\n        <div class=\"aad-philosophy-list\">\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Site Responsive Design\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    The orientation, terrain, surroundings and access\r\n                    of the site influence the way a home is planned.\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Natural Light &amp; Ventilation\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    Openings, courtyards and spatial relationships are\r\n                    considered to create comfortable living environments.\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Functional Planning\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    Spaces are organised around movement, privacy,\r\n                    family routines and everyday usability.\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Timeless Character\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    Materials, proportions and architectural details\r\n                    come together to create a lasting visual identity.\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     ARCHITECTURAL ELEMENTS\r\n========================================================= -->\r\n\r\n<section class=\"aad-elements\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-elements-heading\">\r\n\r\n            <div class=\"aad-elements-label\">\r\n                Design Considerations\r\n            </div>\r\n\r\n            <h2 class=\"aad-elements-title\">\r\n                Every detail has a\r\n                <span>reason.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-sun\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Light\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Natural daylight is considered from the earliest\r\n                        stages of planning to create bright and comfortable\r\n                        interiors.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-wind\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Air\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Cross ventilation and carefully positioned openings\r\n                        help create spaces that feel fresh and connected\r\n                        to the outdoors.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-house\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Comfort\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Room proportions, circulation and spatial hierarchy\r\n                        are shaped around the practical needs of everyday life.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-leaf\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Landscape\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Green spaces, courtyards and outdoor areas can become\r\n                        natural extensions of the home.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-layer-group\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Materials\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Finishes and materials are selected to complement\r\n                        the architecture while remaining practical and durable.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-compass-drafting\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Detail\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Architectural details add character to the home\r\n                        without compromising its overall simplicity.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     FEATURE IMAGE\r\n========================================================= -->\r\n\r\n<section class=\"aad-feature\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"aad-feature-content\">\r\n\r\n                    <div class=\"aad-feature-label\">\r\n                        From Concept To Home\r\n                    </div>\r\n\r\n                    <h2 class=\"aad-feature-title\">\r\n                        From an idea\r\n                        to a place you\r\n                        <span>call home.</span>\r\n                    </h2>\r\n\r\n                    <p class=\"aad-feature-text\">\r\n                        Architectural design is where your requirements,\r\n                        the site and the possibilities of construction\r\n                        come together.\r\n                    </p>\r\n\r\n                    <div class=\"aad-feature-list\">\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Understanding your requirements\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Studying the site and surroundings\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Developing the architectural concept\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Planning spaces around your lifestyle\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Creating a clear path towards construction\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"aad-feature-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images//arun-bhandary-builders-architectural-design-interior.jpg\"\r\n                        alt=\"Contemporary architectural interior design\"\r\n                        loading=\"lazy\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     DESIGN JOURNEY\r\n========================================================= -->\r\n\r\n<section class=\"aad-journey\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-journey-heading\">\r\n\r\n            <div class=\"aad-journey-label\">\r\n                The Design Journey\r\n            </div>\r\n\r\n            <h2 class=\"aad-journey-title\">\r\n                A thoughtful process\r\n                from <span>idea to detail.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Understanding\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        We begin by understanding your plot, lifestyle,\r\n                        requirements, priorities and vision for your home.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Planning\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        The available space is organised carefully to\r\n                        balance functionality, movement, privacy and\r\n                        natural surroundings.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Concept\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        The architectural language begins to take shape\r\n                        through form, proportions, materials and spatial\r\n                        relationships.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Refinement\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        Details, finishes, lighting and functional elements\r\n                        are refined to bring clarity and character to the\r\n                        design.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Coordination\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        Architectural thinking is aligned with construction\r\n                        requirements to help create a practical path from\r\n                        design to execution.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Your Home\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        The finished design becomes the foundation for\r\n                        creating a home that reflects your personality,\r\n                        needs and way of living.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CTA\r\n========================================================= -->\r\n\r\n<section class=\"aad-cta\" id=\"contact\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-cta-content\">\r\n\r\n            <div class=\"aad-cta-label\">\r\n                Start With An Idea\r\n            </div>\r\n\r\n            <h2 class=\"aad-cta-title\">\r\n                Let\'s design a home\r\n                that feels like yours.\r\n            </h2>\r\n\r\n            <p class=\"aad-cta-text\">\r\n                Have a plot or a home idea in mind?\r\n                Let\'s talk about your requirements and explore\r\n                the possibilities together.\r\n            </p>\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/contact-us\" class=\"aad-cta-button\">\r\n                Discuss Your Project\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n            </a>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <div class=\"aad-cta-decoration\"></div>\r\n\r\n</section>\r\n\r\n</article>', 'Archetectural & Design', '', 'publish', 'closed', 'closed', '', 'archetectural-design', '', '', '2026-10-30 11:43:36', '2026-10-30 11:43:36', '', 0, 'http://localhost/arun-bhandary-builders/?page_id=61', 0, 'page', '', 0),
(62, 1, '2026-10-30 11:43:36', '2026-10-30 11:43:36', '<article>\r\n    \r\n\r\n<!-- =========================================================\r\n     HERO\r\n========================================================= -->\r\n\r\n<section class=\"aad-hero\">\r\n\r\n    <!-- Breadcrumb inside Hero -->\r\n    <div class=\"aad-breadcrumb-wrap\">\r\n        <div class=\"container\">\r\n            <nav aria-label=\"breadcrumb\">\r\n                <ol class=\"breadcrumb aad-breadcrumb\">\r\n                    <li class=\"breadcrumb-item\">\r\n                        <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n                    </li>\r\n\r\n                    <li class=\"breadcrumb-item\">\r\n                        <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">Services</a>\r\n                    </li>\r\n\r\n                    <li class=\"breadcrumb-item active\" aria-current=\"page\">\r\n                        Architectural &amp; Design\r\n                    </li>\r\n                </ol>\r\n            </nav>\r\n        </div>\r\n    </div>\r\n\r\n\r\n    <div class=\"container\">\r\n        <div class=\"row align-items-center aad-hero-main\">\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"aad-hero-content\">\r\n\r\n                    <div class=\"aad-hero-kicker\">\r\n                        <span class=\"aad-hero-kicker-line\"></span>\r\n                        Architectural &amp; Design\r\n                    </div>\r\n\r\n                    <h1 class=\"aad-hero-title\">\r\n                        Spaces\r\n                        <span>With Purpose.</span>\r\n                    </h1>\r\n\r\n                    <p class=\"aad-hero-description\">\r\n                        Thoughtful architecture brings together the way you live,\r\n                        the character of the site and the possibilities of design\r\n                        to create spaces that feel naturally yours.\r\n                    </p>\r\n\r\n                    <div class=\"aad-hero-actions\">\r\n\r\n                        <a href=\"#design\" class=\"aad-hero-button\">\r\n                            Explore Our Approach\r\n                            <i class=\"fa-solid fa-arrow-down\"></i>\r\n                        </a>\r\n\r\n                        <a href=\"#contact\" class=\"aad-hero-link\">\r\n                            Discuss Your Project\r\n                        </a>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"aad-hero-image-wrap\">\r\n\r\n                    <div class=\"aad-hero-image\">\r\n\r\n                        <img\r\n                            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images//arun-bhandary-builders-architectural-design-hero.jpg\"\r\n                            alt=\"Architectural design of a contemporary home\"\r\n                            loading=\"eager\"\r\n                        >\r\n\r\n                        <div class=\"aad-hero-image-label\">\r\n                            <small>Design Approach</small>\r\n                            <strong>Form + Function</strong>\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     INTRO\r\n========================================================= -->\r\n\r\n<section class=\"aad-intro\" id=\"design\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-intro-label\">\r\n            <span class=\"aad-intro-label-line\"></span>\r\n            The Design Perspective\r\n        </div>\r\n\r\n        <h2 class=\"aad-intro-title\">\r\n            Architecture that feels\r\n            <span>personal.</span>\r\n        </h2>\r\n\r\n        <p class=\"aad-intro-text\">\r\n            A well-designed home is more than an attractive elevation.\r\n            It is about understanding the site, natural light, movement,\r\n            privacy, proportions and the everyday routines of the people\r\n            who will live there.\r\n        </p>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     IMAGE STORY\r\n========================================================= -->\r\n\r\n<section class=\"aad-story\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"row g-0 align-items-stretch\">\r\n\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"aad-story-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images//arun-bhandary-builders-architectural-design-home.jpg\"\r\n                        alt=\"Contemporary residential architectural design\"\r\n                        loading=\"lazy\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"aad-story-side\">\r\n\r\n                    <div class=\"aad-story-side-label\">\r\n                        Beyond The Elevation\r\n                    </div>\r\n\r\n                    <h2 class=\"aad-story-side-title\">\r\n                        Designed around\r\n                        <span style=\"color: var(--aad-red);\">\r\n                            your life.\r\n                        </span>\r\n                    </h2>\r\n\r\n                    <p class=\"aad-story-side-text\">\r\n                        From the first concept to the final details,\r\n                        our design approach considers how every space\r\n                        connects with the next.\r\n                    </p>\r\n\r\n                    <p class=\"aad-story-side-text\">\r\n                        The result is a home that balances aesthetics,\r\n                        comfort, functionality and long-term value.\r\n                    </p>\r\n\r\n                    <div class=\"aad-story-note\">\r\n                        Thoughtful planning. Meaningful spaces.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     PHILOSOPHY\r\n========================================================= -->\r\n\r\n<section class=\"aad-philosophy\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-philosophy-label\">\r\n            Our Design Philosophy\r\n        </div>\r\n\r\n        <h2 class=\"aad-philosophy-title\">\r\n            Good architecture\r\n            should look beautiful,\r\n            <span>feel natural</span>\r\n            and work effortlessly.\r\n        </h2>\r\n\r\n        <p class=\"aad-philosophy-description\">\r\n            Every design decision has a purpose. We look beyond trends\r\n            to create homes that remain comfortable, relevant and\r\n            visually balanced over time.\r\n        </p>\r\n\r\n\r\n        <div class=\"aad-philosophy-list\">\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Site Responsive Design\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    The orientation, terrain, surroundings and access\r\n                    of the site influence the way a home is planned.\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Natural Light &amp; Ventilation\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    Openings, courtyards and spatial relationships are\r\n                    considered to create comfortable living environments.\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Functional Planning\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    Spaces are organised around movement, privacy,\r\n                    family routines and everyday usability.\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"aad-philosophy-item\">\r\n\r\n                <div class=\"aad-philosophy-item-title\">\r\n                    Timeless Character\r\n                </div>\r\n\r\n                <div class=\"aad-philosophy-item-text\">\r\n                    Materials, proportions and architectural details\r\n                    come together to create a lasting visual identity.\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     ARCHITECTURAL ELEMENTS\r\n========================================================= -->\r\n\r\n<section class=\"aad-elements\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-elements-heading\">\r\n\r\n            <div class=\"aad-elements-label\">\r\n                Design Considerations\r\n            </div>\r\n\r\n            <h2 class=\"aad-elements-title\">\r\n                Every detail has a\r\n                <span>reason.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-sun\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Light\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Natural daylight is considered from the earliest\r\n                        stages of planning to create bright and comfortable\r\n                        interiors.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-wind\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Air\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Cross ventilation and carefully positioned openings\r\n                        help create spaces that feel fresh and connected\r\n                        to the outdoors.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-house\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Comfort\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Room proportions, circulation and spatial hierarchy\r\n                        are shaped around the practical needs of everyday life.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-leaf\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Landscape\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Green spaces, courtyards and outdoor areas can become\r\n                        natural extensions of the home.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-layer-group\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Materials\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Finishes and materials are selected to complement\r\n                        the architecture while remaining practical and durable.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-element\">\r\n\r\n                    <div class=\"aad-element-icon\">\r\n                        <i class=\"fa-solid fa-compass-drafting\"></i>\r\n                    </div>\r\n\r\n                    <h3 class=\"aad-element-title\">\r\n                        Detail\r\n                    </h3>\r\n\r\n                    <p class=\"aad-element-text\">\r\n                        Architectural details add character to the home\r\n                        without compromising its overall simplicity.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     FEATURE IMAGE\r\n========================================================= -->\r\n\r\n<section class=\"aad-feature\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n            <div class=\"col-lg-5\">\r\n\r\n                <div class=\"aad-feature-content\">\r\n\r\n                    <div class=\"aad-feature-label\">\r\n                        From Concept To Home\r\n                    </div>\r\n\r\n                    <h2 class=\"aad-feature-title\">\r\n                        From an idea\r\n                        to a place you\r\n                        <span>call home.</span>\r\n                    </h2>\r\n\r\n                    <p class=\"aad-feature-text\">\r\n                        Architectural design is where your requirements,\r\n                        the site and the possibilities of construction\r\n                        come together.\r\n                    </p>\r\n\r\n                    <div class=\"aad-feature-list\">\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Understanding your requirements\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Studying the site and surroundings\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Developing the architectural concept\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Planning spaces around your lifestyle\r\n                        </div>\r\n\r\n                        <div class=\"aad-feature-list-item\">\r\n                            <i class=\"fa-solid fa-check\"></i>\r\n                            Creating a clear path towards construction\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-7\">\r\n\r\n                <div class=\"aad-feature-image\">\r\n\r\n                    <img\r\n                        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images//arun-bhandary-builders-architectural-design-interior.jpg\"\r\n                        alt=\"Contemporary architectural interior design\"\r\n                        loading=\"lazy\"\r\n                    >\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     DESIGN JOURNEY\r\n========================================================= -->\r\n\r\n<section class=\"aad-journey\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-journey-heading\">\r\n\r\n            <div class=\"aad-journey-label\">\r\n                The Design Journey\r\n            </div>\r\n\r\n            <h2 class=\"aad-journey-title\">\r\n                A thoughtful process\r\n                from <span>idea to detail.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Understanding\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        We begin by understanding your plot, lifestyle,\r\n                        requirements, priorities and vision for your home.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Planning\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        The available space is organised carefully to\r\n                        balance functionality, movement, privacy and\r\n                        natural surroundings.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Concept\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        The architectural language begins to take shape\r\n                        through form, proportions, materials and spatial\r\n                        relationships.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Refinement\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        Details, finishes, lighting and functional elements\r\n                        are refined to bring clarity and character to the\r\n                        design.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Coordination\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        Architectural thinking is aligned with construction\r\n                        requirements to help create a practical path from\r\n                        design to execution.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-4 col-md-6\">\r\n\r\n                <div class=\"aad-journey-item\">\r\n\r\n                    <h3 class=\"aad-journey-item-title\">\r\n                        Your Home\r\n                    </h3>\r\n\r\n                    <p class=\"aad-journey-item-text\">\r\n                        The finished design becomes the foundation for\r\n                        creating a home that reflects your personality,\r\n                        needs and way of living.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n\r\n<!-- =========================================================\r\n     CTA\r\n========================================================= -->\r\n\r\n<section class=\"aad-cta\" id=\"contact\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"aad-cta-content\">\r\n\r\n            <div class=\"aad-cta-label\">\r\n                Start With An Idea\r\n            </div>\r\n\r\n            <h2 class=\"aad-cta-title\">\r\n                Let\'s design a home\r\n                that feels like yours.\r\n            </h2>\r\n\r\n            <p class=\"aad-cta-text\">\r\n                Have a plot or a home idea in mind?\r\n                Let\'s talk about your requirements and explore\r\n                the possibilities together.\r\n            </p>\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/contact-us\" class=\"aad-cta-button\">\r\n                Discuss Your Project\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n            </a>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n    <div class=\"aad-cta-decoration\"></div>\r\n\r\n</section>\r\n\r\n</article>', 'Archetectural & Design', '', 'inherit', 'closed', 'closed', '', '61-revision-v1', '', '', '2026-10-30 11:43:36', '2026-10-30 11:43:36', '', 61, 'http://localhost/arun-bhandary-builders/?p=62', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(63, 1, '2026-10-30 11:47:28', '2026-10-30 11:47:28', '    <article>\r\n        <!-- =========================================================\r\n         HERO\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-hero\">\r\n\r\n            <div class=\"accn2-hero-top\">\r\n                <div class=\"container\">\r\n                    <nav class=\"accn2-breadcrumb\" aria-label=\"Breadcrumb\">\r\n\r\n                        <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n\r\n                        <i class=\"fa-solid fa-chevron-right\"></i>\r\n\r\n                        <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">Services</a>\r\n\r\n                        <i class=\"fa-solid fa-chevron-right\"></i>\r\n\r\n                        <span>Construction Consultation</span>\r\n\r\n                    </nav>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"accn2-hero-main\">\r\n                <div class=\"container\">\r\n\r\n                    <div class=\"row align-items-center g-5\">\r\n\r\n                        <div class=\"col-lg-6\">\r\n\r\n                            <div class=\"accn2-hero-copy\">\r\n\r\n                                <div class=\"accn2-eyebrow\">\r\n                                    <span></span>\r\n                                    Construction Consultation\r\n                                </div>\r\n\r\n                                <h1 class=\"accn2-hero-title\">\r\n                                    Think.<br>\r\n                                    Plan.<br>\r\n                                    <em>Build.</em>\r\n                                </h1>\r\n\r\n                                <p class=\"accn2-hero-description\">\r\n                                    Good construction begins with good decisions.\r\n                                    Get the right direction before you begin planning,\r\n                                    designing and building your home.\r\n                                </p>\r\n\r\n                                <a href=\"#accn2-topics\" class=\"accn2-hero-link\">\r\n                                    Explore Consultation\r\n                                    <i class=\"fa-solid fa-arrow-right\"></i>\r\n                                </a>\r\n\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                        <div class=\"col-lg-6\">\r\n\r\n                            <div class=\"accn2-hero-image-wrap\">\r\n\r\n                                <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-construction-consultation-hero.jpg\"\r\n                                    alt=\"Construction consultation and residential planning\" class=\"accn2-hero-image\"\r\n                                    loading=\"eager\">\r\n\r\n\r\n\r\n                                <div class=\"accn2-hero-caption\">\r\n                                    Plan With Confidence\r\n                                </div>\r\n\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         INTRO\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-intro\">\r\n\r\n            <div class=\"container\">\r\n\r\n                <div class=\"accn2-intro-label\">\r\n                    The Right Beginning\r\n                </div>\r\n\r\n                <h2 class=\"accn2-intro-title\">\r\n                    Before construction begins,\r\n                    <strong>clarity matters.</strong>\r\n                </h2>\r\n\r\n                <p class=\"accn2-intro-text\">\r\n                    Whether you already own a plot or are still deciding where\r\n                    and how to build, thoughtful consultation can help you\r\n                    understand the possibilities, evaluate practical considerations\r\n                    and move forward with greater confidence.\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         CONSULTATION TOPICS\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-topics\" id=\"accn2-topics\">\r\n\r\n            <div class=\"container\">\r\n\r\n                <div class=\"accn2-section-label\">\r\n                    What We Discuss\r\n                </div>\r\n\r\n                <h2 class=\"accn2-section-title\">\r\n                    Ideas become clearer when the right questions are asked.\r\n                </h2>\r\n\r\n                <div class=\"accn2-topic-list\">\r\n\r\n                    <div class=\"accn2-topic\">\r\n\r\n                        <div class=\"accn2-topic-icon\">\r\n                            <i class=\"fa-solid fa-location-dot\"></i>\r\n                        </div>\r\n\r\n                        <div class=\"accn2-topic-content\">\r\n\r\n                            <h3 class=\"accn2-topic-title\">\r\n                                Plot & Location\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-topic-text\">\r\n                                Understand how the location, plot dimensions,\r\n                                surroundings and accessibility can influence\r\n                                your home planning.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"accn2-topic\">\r\n\r\n                        <div class=\"accn2-topic-icon\">\r\n                            <i class=\"fa-solid fa-compass-drafting\"></i>\r\n                        </div>\r\n\r\n                        <div class=\"accn2-topic-content\">\r\n\r\n                            <h3 class=\"accn2-topic-title\">\r\n                                Home Design\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-topic-text\">\r\n                                Discuss the kind of home you want and explore\r\n                                how your lifestyle and requirements can influence\r\n                                the design direction.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"accn2-topic\">\r\n\r\n                        <div class=\"accn2-topic-icon\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                        </div>\r\n\r\n                        <div class=\"accn2-topic-content\">\r\n\r\n                            <h3 class=\"accn2-topic-title\">\r\n                                Space Planning\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-topic-text\">\r\n                                Consider room requirements, movement, privacy,\r\n                                natural light and practical use of available space.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"accn2-topic\">\r\n\r\n                        <div class=\"accn2-topic-icon\">\r\n                            <i class=\"fa-solid fa-indian-rupee-sign\"></i>\r\n                        </div>\r\n\r\n                        <div class=\"accn2-topic-content\">\r\n\r\n                            <h3 class=\"accn2-topic-title\">\r\n                                Budget Considerations\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-topic-text\">\r\n                                Build a clearer understanding of priorities,\r\n                                construction requirements and the factors that\r\n                                influence overall project planning.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"accn2-topic\">\r\n\r\n                        <div class=\"accn2-topic-icon\">\r\n                            <i class=\"fa-solid fa-helmet-safety\"></i>\r\n                        </div>\r\n\r\n                        <div class=\"accn2-topic-content\">\r\n\r\n                            <h3 class=\"accn2-topic-title\">\r\n                                Construction Approach\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-topic-text\">\r\n                                Understand the broad construction journey and\r\n                                the decisions involved from planning through\r\n                                completion.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         IMAGE STORY\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-story\">\r\n\r\n            <div class=\"container\">\r\n\r\n                <div class=\"row align-items-center g-5\">\r\n\r\n                    <div class=\"col-lg-6\">\r\n\r\n                        <div class=\"accn2-story-image-wrap\">\r\n\r\n                            <div class=\"accn2-story-accent\"></div>\r\n\r\n                            <img src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-construction-consultation-planning.jpg\"\r\n                                alt=\"Planning a residential home\" class=\"accn2-story-image\" loading=\"lazy\">\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                    <div class=\"col-lg-6\">\r\n\r\n                        <div class=\"accn2-story-copy\">\r\n\r\n                            <div class=\"accn2-section-label\">\r\n                                Your Vision\r\n                            </div>\r\n\r\n                            <h2 class=\"accn2-story-title\">\r\n                                Your home should begin\r\n                                with <span>your needs.</span>\r\n                            </h2>\r\n\r\n                            <p class=\"accn2-story-text\">\r\n                                Every family has different priorities. Some need\r\n                                more bedrooms, some want larger living spaces,\r\n                                while others focus on outdoor areas, privacy,\r\n                                natural light or future flexibility.\r\n                            </p>\r\n\r\n                            <p class=\"accn2-story-text\">\r\n                                Consultation gives you an opportunity to discuss\r\n                                these ideas before they become construction\r\n                                decisions.\r\n                            </p>\r\n\r\n                            <div class=\"accn2-story-note\">\r\n                                A thoughtful plan creates a stronger foundation\r\n                                for the entire home-building journey.\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         GUIDANCE\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-guidance\">\r\n\r\n            <div class=\"container\">\r\n\r\n                <div class=\"accn2-guidance-intro\">\r\n\r\n                    <div class=\"accn2-section-label\">\r\n                        Why Consultation\r\n                    </div>\r\n\r\n                    <h2 class=\"accn2-section-title\">\r\n                        Make informed choices before you build.\r\n                    </h2>\r\n\r\n                </div>\r\n\r\n\r\n                <div class=\"row g-0 accn2-guidance-grid\">\r\n\r\n                    <div class=\"col-md-6 col-lg-3\">\r\n\r\n                        <div class=\"accn2-guidance-item\">\r\n\r\n                            <div class=\"accn2-guidance-number\">\r\n                                CLEARER DIRECTION\r\n                            </div>\r\n\r\n                            <h3 class=\"accn2-guidance-title\">\r\n                                Understand\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-guidance-text\">\r\n                                Gain a clearer picture of what your project\r\n                                may require before moving forward.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"col-md-6 col-lg-3\">\r\n\r\n                        <div class=\"accn2-guidance-item\">\r\n\r\n                            <div class=\"accn2-guidance-number\">\r\n                                BETTER PLANNING\r\n                            </div>\r\n\r\n                            <h3 class=\"accn2-guidance-title\">\r\n                                Organize\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-guidance-text\">\r\n                                Bring your ideas, requirements and priorities\r\n                                together into a more practical direction.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"col-md-6 col-lg-3\">\r\n\r\n                        <div class=\"accn2-guidance-item\">\r\n\r\n                            <div class=\"accn2-guidance-number\">\r\n                                SMARTER CHOICES\r\n                            </div>\r\n\r\n                            <h3 class=\"accn2-guidance-title\">\r\n                                Evaluate\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-guidance-text\">\r\n                                Consider different possibilities and understand\r\n                                what may work best for your requirements.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"col-md-6 col-lg-3\">\r\n\r\n                        <div class=\"accn2-guidance-item\">\r\n\r\n                            <div class=\"accn2-guidance-number\">\r\n                                GREATER CONFIDENCE\r\n                            </div>\r\n\r\n                            <h3 class=\"accn2-guidance-title\">\r\n                                Proceed\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-guidance-text\">\r\n                                Move toward the next stage with a better\r\n                                understanding of your construction journey.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         LARGE IMAGE SECTION\r\n    =========================================================