p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"col-md-6 col-lg-3\">\r\n\r\n                        <div class=\"accn2-guidance-item\">\r\n\r\n                            <div class=\"accn2-guidance-number\">\r\n                                SMARTER CHOICES\r\n                            </div>\r\n\r\n                            <h3 class=\"accn2-guidance-title\">\r\n                                Evaluate\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-guidance-text\">\r\n                                Consider different possibilities and understand\r\n                                what may work best for your requirements.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n\r\n                    <div class=\"col-md-6 col-lg-3\">\r\n\r\n                        <div class=\"accn2-guidance-item\">\r\n\r\n                            <div class=\"accn2-guidance-number\">\r\n                                GREATER CONFIDENCE\r\n                            </div>\r\n\r\n                            <h3 class=\"accn2-guidance-title\">\r\n                                Proceed\r\n                            </h3>\r\n\r\n                            <p class=\"accn2-guidance-text\">\r\n                                Move toward the next stage with a better\r\n                                understanding of your construction journey.\r\n                            </p>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         LARGE IMAGE SECTION\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-visual\">\r\n\r\n            <img src=\"http://localhost/ar