                              </div>\r\n\r\n                                <div>\r\n                                    <h3 class=\"accn2-audience-name\">\r\n                                        Plot Owners\r\n                                    </h3>\r\n\r\n                                    <p class=\"accn2-audience-text\">\r\n                                        For those who already own a plot and\r\n                                        want to understand the next steps.\r\n                                    </p>\r\n                                </div>\r\n\r\n                            </div>\r\n\r\n\r\n                            <div class=\"accn2-audience-item\">\r\n\r\n                                <div class=\"accn2-audience-icon\">\r\n                                    <i class=\"fa-solid fa-house-chimney\"></i>\r\n                                </div>\r\n\r\n                                <div>\r\n                                    <h3 class=\"accn2-audience-name\">\r\n                                        First-Time Homeowners\r\n                                    </h3>\r\n\r\n                                    <p class=\"accn2-audience-text\">\r\n                                        For families beginning to explore\r\n                                        customized home construction.\r\n                                    </p>\r\n                                </div>\r\n\r\n                            </div>\r\n\r\n\r\n                            <div class=\"accn2-audience-item\">\r\n\r\n                                <div class=\"accn2-audience-icon\">\r\n                                    <i class=\"fa-solid fa-people-roof\"></i>\r\n                                </div>\r\n\r\n                                <div>\r\n                                    <h3 class=\"accn2-audience-name\">\r\n                                        Families With Ideas\r\n                                    </h3>\r\n\r\n                                    <p class=\"accn2-audience-text\">\r\n                                        For people who have ideas for their\r\n                                        home but need help shaping them.\r\n                                    </p>\r\n                                </div>\r\n\r\n                            </div>\r\n\r\n\r\n                            <div class=\"accn2-audience-item\">\r\n\r\n                                <div class=\"accn2-audience-icon\">\r\n                                    <i class=\"fa-solid fa-landmark\"></i>\r\n                                </div>\r\n\r\n                                <div>\r\n                                    <h3 class=\"accn2-audience-name\">\r\n                                        Landowners\r\n                                    </h3>\r\n\r\n                                    <p class=\"accn2-audience-text\">\r\n                                        For landowners interested in discussing\r\n                                        development possibilities and opportunities.\r\n                                    </p>\r\n                                </div>\r\n\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         CONTACT STRIP\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-contact\">\r\n\r\n            <div class=\"container\">\r\n\r\n                <div class=\"row align-items-center\">\r\n\r\n                    <div class=\"col-lg-7\">\r\n\r\n                        <h2 class=\"accn2-contact-title\">\r\n                            Have A Construction Idea?\r\n                        </h2>\r\n\r\n                        <p class=\"accn2-contact-text\">\r\n                            Speak with Arun Bhandary Builders & Developers\r\n                            and start with the right conversation.\r\n                        </p>\r\n\r\n                    </div>\r\n\r\n                    <div class=\"col-lg-5\">\r\n\r\n                        <div class=\"accn2-contact-actions\">\r\n\r\n                            <a href=\"tel:+918904819565\" class=\"accn2-contact-button\">\r\n                                <i class=\"fa-solid fa-phone\"></i>\r\n                                +91 8904 819 565\r\n                            </a>\r\n\r\n                            <a href=\"https://wa.me/918904819565\" target=\"_blank\" rel=\"noopener\"\r\n                                class=\"accn2-contact-button\">\r\n                                <i class=\"fa-brands fa-whatsapp\"></i>\r\n                                WhatsApp\r\n                            </a>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </section>\r\n\r\n\r\n        <!-- =========================================================\r\n         LOCATIONS\r\n    ========================================================= -->\r\n\r\n        <section class=\"accn2-locations\">\r\n\r\n            <div class=\"container\">\r\n\r\n                <div class=\"accn2-location-heading\">\r\n                    Serving Homeowners Across\r\n                </div>\r\n\r\n                <div class=\"accn2-location-list\">\r\n\r\n                    <div class=\"accn2-location\">\r\n                        <i class=\"fa-solid fa-location-dot\"></i>\r\n                        Mangaluru\r\n                    </div>\r\n\r\n                    <div class=\"accn2-location\">\r\n                        <i class=\"fa-solid fa-location-dot\"></i>\r\n                        Udupi\r\n                    </div>\r\n\r\n                    <div class=\"accn2-location\">\r\n                        <i class=\"fa-solid fa-loca