(66, 1, '2026-10-30 11:52:12', '2026-10-30 11:52:12', '<article>\r\n    <!-- =====================================================\r\n     HERO\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-hero\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-hero-inner\">\r\n\r\n            <!-- BREADCRUMB -->\r\n\r\n            <div class=\"ajv6-hero-breadcrumb\">\r\n\r\n                <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n\r\n                <span>/</span>\r\n\r\n                <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">Services</a>\r\n\r\n                <span>/</span>\r\n\r\n                <strong>Joint Venture</strong>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"ajv6-hero-red-line\"></div>\r\n\r\n\r\n            <!-- TITLE -->\r\n\r\n            <div class=\"ajv6-hero-title-wrap\">\r\n\r\n                <div class=\"ajv6-hero-small\">\r\n                    Joint Venture Opportunities\r\n                </div>\r\n\r\n                <h1 class=\"ajv6-hero-title\">\r\n                    YOUR\r\n                    <span>LAND.</span>\r\n                    OUR\r\n                    <span>VISION.</span>\r\n                </h1>\r\n\r\n                <p class=\"ajv6-hero-subtitle\">\r\n                    Bringing together land, planning and construction\r\n                    expertise to create thoughtfully developed\r\n                    residential opportunities.\r\n                </p>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- HERO IMAGE -->\r\n\r\n            <div class=\"ajv6-hero-image\">\r\n\r\n                <img\r\n                    src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-joint-venture-hero.jpg\"\r\n                    alt=\"Joint venture residential development\"\r\n                    loading=\"eager\"\r\n                >\r\n\r\n                <div class=\"ajv6-hero-caption\">\r\n                    Land · Design · Development\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RED JV BLOCK -->\r\n\r\n            <div class=\"ajv6-hero-jv\">\r\n\r\n                <strong>JV</strong>\r\n\r\n                <span>\r\n                    Partnership\r\n                </span>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     OPENING\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-opening\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-opening-label\">\r\n            The Opportunity\r\n        </div>\r\n\r\n        <h2 class=\"ajv6-opening-title\">\r\n            Some land is waiting for\r\n            <span>the right idea.</span>\r\n        </h2>\r\n\r\n        <div class=\"row ajv6-opening-bottom\">\r\n\r\n            <div class=\"col-lg-8\">\r\n\r\n                <p class=\"ajv6-opening-copy\">\r\n                    A Joint Venture allows landowners to bring\r\n                    their property together with our experience in\r\n                    planning, design and construction. Together,\r\n                    we explore what the land can become and shape\r\n                    a residential development around its potential.\r\n                </p>\r\n\r\n            </div>\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ajv6-opening-side\">\r\n\r\n                    <div class=\"ajv6-opening-side-text\">\r\n                        The objective is simple — understand the\r\n                        property, identify its possibilities and\r\n                        create a thoughtful development direction.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     LANDOWNER\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-landowner\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-landowner-heading\">\r\n\r\n            <div class=\"ajv6-label\">\r\n                For Landowners\r\n            </div>\r\n\r\n            <h2>\r\n                Your property has a story.\r\n                <span>Let\'s shape its next chapter.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-landowner-photo\">\r\n\r\n                    <div class=\"ajv6-landowner-photo-main\">\r\n\r\n                        <img\r\n                            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-image-for-joint-venture-land.jpg\"\r\n                            alt=\"Land development opportunity\"\r\n                            loading=\"lazy\"\r\n                        >\r\n\r\n                    </div>\r\n\r\n                    <div class=\"ajv6-landowner-photo-small\">\r\n\r\n                        <img\r\n                            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-joint-venture-development.jp.jpg\"\r\n                            alt=\"Residential development\"\r\n                            loading=\"lazy\"\r\n                        >\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-landowner-content\">\r\n\r\n                    <p>\r\n                        We work with landowners who are looking\r\n                        to explore the residential development\r\n                        potential of their property.\r\n                    </p>\r\n\r\n                    <p class=\"mt-4\">\r\n                        From understanding the site and planning\r\n                        the development to construction and\r\n                        completion, our expertise supports the\r\n                        journey from land to a thoughtfully created\r\n                        residential environment.\r\n                    </p>\r\n\r\n\r\n                    <div class=\"ajv6-landowner-list\">\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                            <span>\r\n                                Location &amp; site understanding\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-compass-drafting\"></i>\r\n\r\n                            <span>\r\n                                Development planning &amp; design\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-building\"></i>\r\n\r\n                            <span>\r\n                                Construction expertise\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-handshake\"></i>\r\n\r\n                            <span>\r\n                                Collaborative partnership\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     QUOTE\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-quote\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-quote-mark\">\r\n            “\r\n        </div>\r\n\r\n        <h2 class=\"ajv6-quote-text\">\r\n            Good development is not just about\r\n            building on land. It is about understanding\r\n            <span>what that land can become.</span>\r\n        </h2>\r\n\r\n        <div class=\"ajv6-quote-caption\">\r\n            Our Development Philosophy\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     EXPERTISE\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-expertise\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-expertise-heading\">\r\n\r\n            <div class=\"ajv6-label\">\r\n                What We Bring\r\n            </div>\r\n\r\n            <h2>\r\n                Turning potential into a\r\n                <span>planned opportunity.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-map-location-dot\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Site Understanding\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Understanding the location, land characteristics\r\n                        and possibilities before establishing the\r\n                        development direction.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                \r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-pen-ruler\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Planning &amp; Design\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Developing thoughtful residential concepts\r\n                        that respond to the property and its\r\n                        surrounding context.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                \r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-person-digging\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Construction\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Bringing the planned development to life\r\n                        through organised construction and careful\r\n                        attention to quality.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                \r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-arrows-to-circle\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Project Coordination\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Coordinating the different stages of the\r\n                        development journey towards completion.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                \r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     IMAGE STATEMENT\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-image-section\">\r\n\r\n    <img\r\n        src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-joint-venture-development.jpg\"\r\n        alt=\"Residential development project\"\r\n        loading=\"lazy\"\r\n    >\r\n\r\n    <div class=\"ajv6-image-section-overlay\"></div>\r\n\r\n    <div class=\"ajv6-image-content\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <div class=\"ajv6-image-content-inner\">\r\n\r\n                <div class=\"ajv6-label\">\r\n                    From Land To Place\r\n                </div>\r\n\r\n                <h2 class=\"ajv6-image-title\">\r\n                    Create a development\r\n                    that feels <span>at home.</span>\r\n                </h2>\r\n\r\n                <p class=\"ajv6-image-text\">\r\n                    Our focus is on creating residential environments\r\n                    that are thoughtfully planned, practical to live\r\n                    in and carefully constructed.\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     OPPORTUNITY\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-opportunity\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-opportunity-heading\">\r\n\r\n            <div class=\"ajv6-label\">\r\n                Partnership Approach\r\n            </div>\r\n\r\n            <h2>\r\n                One property.\r\n                <span>Many possibilities.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row g-5\">\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-opportunity-item\">\r\n\r\n                    <i class=\"fa-solid fa-magnifying-glass-location\"></i>\r\n\r\n                    <h3>\r\n                        Understand\r\n                    </h3>\r\n\r\n                    <p>\r\n                        We begin by understanding the property,\r\n                        its location and the opportunities it may\r\n                        offer for residential development.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-opportunity-item\">\r\n\r\n                    <i class=\"fa-solid fa-compass-drafting\"></i>\r\n\r\n                    <h3>\r\n                        Shape\r\n                    </h3>\r\n\r\n                    <p>\r\n                        We explore planning and design possibilities\r\n                        to create a development direction suited\r\n                        to the land.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-opportunity-item\">\r\n\r\n                    <i class=\"fa-solid fa-trowel-bricks\"></i>\r\n\r\n                    <h3>\r\n                        Build\r\n                    </h3>\r\n\r\n                    <p>\r\n                        Our construction expertise helps transform\r\n                        the planned concept into a completed\r\n                        residential development.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-opportunity-item\">\r\n\r\n                    <i class=\"fa-solid fa-house-circle-check\"></i>\r\n\r\n                    <h3>\r\n                        Complete\r\n                    </h3>\r\n\r\n                    <p>\r\n                        The result is a thoughtfully developed\r\n                        residential environment designed around\r\n                        quality and long-term usability.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     LOCATIONS\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-locations\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-label\">\r\n            Areas We Serve\r\n        </div>\r\n\r\n        <h2 class=\"ajv6-locations-title\">\r\n            Exploring development opportunities\r\n            across <span>coastal Karnataka.</span>\r\n        </h2>\r\n\r\n\r\n        <div class=\"ajv6-location-strip\">\r\n\r\n            <div class=\"ajv6-location\">\r\n\r\n                <div class=\"row align-items-center\">\r\n\r\n                    <div class=\"col-md-6\">\r\n\r\n                        <strong>\r\n                            Mangaluru\r\n                        </strong>\r\n\r\n                    </div>\r\n\r\n                    <div class=\"col-md-6 text-md-end\">\r\n\r\n                        <span>\r\n                            Residential Development\r\n                        </span>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"ajv6-location\">\r\n\r\n                <div class=\"row align-items-center\">\r\n\r\n                    <div class=\"col-md-6\">\r\n\r\n                        <strong>\r\n                            Udupi\r\n                        </strong>\r\n\r\n                    </div>\r\n\r\n                    <div class=\"col-md-6 text-md-end\">\r\n\r\n                        <span>\r\n                            Residential Development\r\n                        </span>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"ajv6-location\">\r\n\r\n                <div class=\"row align-items-center\">\r\n\r\n                    <div class=\"col-md-6\">\r\n\r\n                        <strong>\r\n                            Moodabidire\r\n                        </strong>\r\n\r\n                    </div>\r\n\r\n                    <div class=\"col-md-6 text-md-end\">\r\n\r\n                        <span>\r\n                            Residential Development\r\n                        </span>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     CTA\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-cta\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-cta-content\">\r\n\r\n            <div class=\"ajv6-cta-label\">\r\n                Start A Conversation\r\n            </div>\r\n\r\n            <h2 class=\"ajv6-cta-title\">\r\n                Have land with potential?\r\n            </h2>\r\n\r\n            <p class=\"ajv6-cta-text\">\r\n                Let\'s explore what your property could become.\r\n                Connect with Arun Bhandary Builders &amp; Developers\r\n                to discuss a possible Joint Venture opportunity.\r\n            </p>\r\n\r\n            <a href=\"http://localhost/arun-bhandary-builders/contact-us\" class=\"ajv6-cta-button\">\r\n                Discuss Your Land\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n            </a>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n</article>', 'Joint Venture', '', 'publish', 'closed', 'closed', '', 'joint-venture', '', '', '2026-10-30 11:52:12', '2026-10-30 11:52:12', '', 0, 'http://localhost/arun-bhandary-builders/?page_id=66', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(67, 1, '2026-10-30 11:52:12', '2026-10-30 11:52:12', '<article>\r\n    <!-- =====================================================\r\n     HERO\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-hero\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-hero-inner\">\r\n\r\n            <!-- BREADCRUMB -->\r\n\r\n            <div class=\"ajv6-hero-breadcrumb\">\r\n\r\n                <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n\r\n                <span>/</span>\r\n\r\n                <a href=\"http://localhost/arun-bhandary-builders/residential-construction\">Services</a>\r\n\r\n                <span>/</span>\r\n\r\n                <strong>Joint Venture</strong>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"ajv6-hero-red-line\"></div>\r\n\r\n\r\n            <!-- TITLE -->\r\n\r\n            <div class=\"ajv6-hero-title-wrap\">\r\n\r\n                <div class=\"ajv6-hero-small\">\r\n                    Joint Venture Opportunities\r\n                </div>\r\n\r\n                <h1 class=\"ajv6-hero-title\">\r\n                    YOUR\r\n                    <span>LAND.</span>\r\n                    OUR\r\n                    <span>VISION.</span>\r\n                </h1>\r\n\r\n                <p class=\"ajv6-hero-subtitle\">\r\n                    Bringing together land, planning and construction\r\n                    expertise to create thoughtfully developed\r\n                    residential opportunities.\r\n                </p>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- HERO IMAGE -->\r\n\r\n            <div class=\"ajv6-hero-image\">\r\n\r\n                <img\r\n                    src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-joint-venture-hero.jpg\"\r\n                    alt=\"Joint venture residential development\"\r\n                    loading=\"eager\"\r\n                >\r\n\r\n                <div class=\"ajv6-hero-caption\">\r\n                    Land · Design · Development\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <!-- RED JV BLOCK -->\r\n\r\n            <div class=\"ajv6-hero-jv\">\r\n\r\n                <strong>JV</strong>\r\n\r\n                <span>\r\n                    Partnership\r\n                </span>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     OPENING\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-opening\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-opening-label\">\r\n            The Opportunity\r\n        </div>\r\n\r\n        <h2 class=\"ajv6-opening-title\">\r\n            Some land is waiting for\r\n            <span>the right idea.</span>\r\n        </h2>\r\n\r\n        <div class=\"row ajv6-opening-bottom\">\r\n\r\n            <div class=\"col-lg-8\">\r\n\r\n                <p class=\"ajv6-opening-copy\">\r\n                    A Joint Venture allows landowners to bring\r\n                    their property together with our experience in\r\n                    planning, design and construction. Together,\r\n                    we explore what the land can become and shape\r\n                    a residential development around its potential.\r\n                </p>\r\n\r\n            </div>\r\n\r\n            <div class=\"col-lg-4\">\r\n\r\n                <div class=\"ajv6-opening-side\">\r\n\r\n                    <div class=\"ajv6-opening-side-text\">\r\n                        The objective is simple — understand the\r\n                        property, identify its possibilities and\r\n                        create a thoughtful development direction.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     LANDOWNER\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-landowner\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-landowner-heading\">\r\n\r\n            <div class=\"ajv6-label\">\r\n                For Landowners\r\n            </div>\r\n\r\n            <h2>\r\n                Your property has a story.\r\n                <span>Let\'s shape its next chapter.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"row align-items-center\">\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-landowner-photo\">\r\n\r\n                    <div class=\"ajv6-landowner-photo-main\">\r\n\r\n                        <img\r\n                            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-image-for-joint-venture-land.jpg\"\r\n                            alt=\"Land development opportunity\"\r\n                            loading=\"lazy\"\r\n                        >\r\n\r\n                    </div>\r\n\r\n                    <div class=\"ajv6-landowner-photo-small\">\r\n\r\n                        <img\r\n                            src=\"http://localhost/arun-bhandary-builders/wp-content/themes/custom-child-theme/assets/images/arun-bhandary-builders-joint-venture-development.jp.jpg\"\r\n                            alt=\"Residential development\"\r\n                            loading=\"lazy\"\r\n                        >\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"col-lg-6\">\r\n\r\n                <div class=\"ajv6-landowner-content\">\r\n\r\n                    <p>\r\n                        We work with landowners who are looking\r\n                        to explore the residential development\r\n                        potential of their property.\r\n                    </p>\r\n\r\n                    <p class=\"mt-4\">\r\n                        From understanding the site and planning\r\n                        the development to construction and\r\n                        completion, our expertise supports the\r\n                        journey from land to a thoughtfully created\r\n                        residential environment.\r\n                    </p>\r\n\r\n\r\n                    <div class=\"ajv6-landowner-list\">\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-location-dot\"></i>\r\n\r\n                            <span>\r\n                                Location &amp; site understanding\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-compass-drafting\"></i>\r\n\r\n                            <span>\r\n                                Development planning &amp; design\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-building\"></i>\r\n\r\n                            <span>\r\n                                Construction expertise\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n\r\n                        <div class=\"ajv6-landowner-row\">\r\n\r\n                            <i class=\"fa-solid fa-handshake\"></i>\r\n\r\n                            <span>\r\n                                Collaborative partnership\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     QUOTE\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-quote\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-quote-mark\">\r\n            “\r\n        </div>\r\n\r\n        <h2 class=\"ajv6-quote-text\">\r\n            Good development is not just about\r\n            building on land. It is about understanding\r\n            <span>what that land can become.</span>\r\n        </h2>\r\n\r\n        <div class=\"ajv6-quote-caption\">\r\n            Our Development Philosophy\r\n        </div>\r\n\r\n    </div>\r\n\r\n</section>\r\n\r\n\r\n<!-- =====================================================\r\n     EXPERTISE\r\n===================================================== -->\r\n\r\n<section class=\"ajv6-expertise\">\r\n\r\n    <div class=\"container\">\r\n\r\n        <div class=\"ajv6-expertise-heading\">\r\n\r\n            <div class=\"ajv6-label\">\r\n                What We Bring\r\n            </div>\r\n\r\n            <h2>\r\n                Turning potential into a\r\n                <span>planned opportunity.</span>\r\n            </h2>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-map-location-dot\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Site Understanding\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Understanding the location, land characteristics\r\n                        and possibilities before establishing the\r\n                        development direction.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                \r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-pen-ruler\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Planning &amp; Design\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Developing thoughtful residential concepts\r\n                        that respond to the property and its\r\n                        surrounding context.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                \r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        <div class=\"ajv6-expertise-row\">\r\n\r\n            <div class=\"row align-items-center\">\r\n\r\n                <div class=\"col-lg-1\">\r\n\r\n                    <div class=\"ajv6-expertise-icon\">\r\n                        <i class=\"fa-solid fa-person-digging\"></i>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-4\">\r\n\r\n                    <div class=\"ajv6-expertise-name\">\r\n                        Construction\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"ajv6-expertise-description\">\r\n                        Bringing the planned development to 