(68, 1, '2026-10-30 11:55:04', '2026-10-30 11:55:04', '<article>\r\n    \r\n    <!-- =========================================================\r\n         HERO\r\n    ========================================================= -->\r\n\r\n    <section class=\"abt9-hero\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <div class=\"abt9-hero-content\">\r\n\r\n                <!-- Breadcrumb -->\r\n                <div class=\"abt9-breadcrumb-wrap\">\r\n                    <ul class=\"abt9-breadcrumb\">\r\n\r\n                        <li>\r\n                            <a href=\"http://localhost/arun-bhandary-builders/\">Home</a>\r\n                        </li>\r\n\r\n                        <li>\r\n                            <i class=\"fa-solid fa-chevron-right\"></i>\r\n                        </li>\r\n\r\n                        <li>\r\n                            Testimonials\r\n                        </li>\r\n\r\n                    </ul>\r\n                </div>\r\n\r\n                <!-- Heading -->\r\n                <div class=\"abt9-kicker\">\r\n                    <span class=\"abt9-kicker-line\"></span>\r\n                    Customer Experiences\r\n                </div>\r\n\r\n                <h1 class=\"abt9-hero-title\">\r\n                    BUILT ON\r\n                    <span>TRUST.</span>\r\n                </h1>\r\n\r\n                <p class=\"abt9-hero-description\">\r\n                    Every home is more than a structure. It is a personal journey,\r\n                    and the experiences of our customers are at the heart of everything\r\n                    we build.\r\n                </p>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"abt9-hero-side\">\r\n            Arun Bhandary Builders &amp; Developers\r\n        </div>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================================\r\n         INTRO\r\n    ========================================================= -->\r\n\r\n    <section class=\"abt9-intro\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <div class=\"row align-items-end g-4\">\r\n\r\n                <div class=\"col-lg-7\">\r\n\r\n                    <div class=\"abt9-intro-label\">\r\n                        What Our Customers Say\r\n                    </div>\r\n\r\n                    <h2 class=\"abt9-intro-title\">\r\n                        Real experiences.\r\n                        <span>Real relationships.</span>\r\n                    </h2>\r\n\r\n                </div>\r\n\r\n                <div class=\"col-lg-5\">\r\n\r\n                    <p class=\"abt9-intro-text\">\r\n                        From selecting the right location and layout to designing\r\n                        and constructing a customized home, every customer\'s journey\r\n                        is unique. These testimonials are dummy content created for\r\n                        page layout and development testing.\r\n                    </p>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </section>\r\n\r\n\r\n    <!-- =========================================================\r\n         TESTIMONIALS\r\n    ========================================================= -->\r\n\r\n    <section class=\"abt9-testimonials\">\r\n\r\n        <div class=\"container\">\r\n\r\n            <div class=\"abt9-section-head\">\r\n\r\n                <div class=\"abt9-section-label\">\r\n                    Customer Stories\r\n                </div>\r\n\r\n                <h2 class=\"abt9-section-title\">\r\n                    Words That Matter.\r\n                </h2>\r\n\r\n                <p class=\"abt9-section-description\">\r\n                    A collection of sample customer experiences designed to\r\n                    demonstrate how the testimonials section can look with\r\n                    multiple reviews.\r\n                </p>\r\n\r\n            </div>\r\n\r\n\r\n            <div class=\"abt9-testimonial-grid\">\r\n\r\n\r\n                <!-- TESTIMONIAL -->\r\n\r\n                <article class=\"abt9-card\">\r\n\r\n                    <div class=\"abt9-quote\">\r\n                        <i class=\"fa-solid fa-quote-left\"></i>\r\n                    </div>\r\n\r\n                    <div class=\"abt9-stars\">\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                    </div>\r\n\r\n                    <p class=\"abt9-review\">\r\n                        The Arun Bhandary Builders & Developers Pvt Ltd delivers top-notch, Quality luxury homes with quality amenities, comes within the budget. Their commitment to quality and amenities is exceptional. Highly recommended for home development.\r\n                    </p>\r\n\r\n                    <div class=\"abt9-card-bottom\">\r\n                        <div>\r\n                            <h3 class=\"abt9-client\">Ashwitha Amin</h3>\r\n                            <div class=\"abt9-client-role\">Home Owner</div>\r\n                        </div>\r\n\r\n                        <div class=\"abt9-client-mark\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                        </div>\r\n                    </div>\r\n\r\n                </article>\r\n\r\n\r\n                <article class=\"abt9-card\">\r\n\r\n                    <div class=\"abt9-quote\">\r\n                        <i class=\"fa-solid fa-quote-left\"></i>\r\n                    </div>\r\n\r\n                    <div class=\"abt9-stars\">\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                    </div>\r\n\r\n                    <p class=\"abt9-review\">\r\n                        I would recommend Home Development. ABBD is known for Quality luxury home with quality amenities, and it\'s within the budget.<br/>\r\n\r\nIn Real Estate, Honesty and integrity are key to building trust with clients. I would recommend them for there quality services and honesty. Best of luck 👍\r\n                    </p>\r\n\r\n                    <div class=\"abt9-card-bottom\">\r\n                        <div>\r\n                            <h3 class=\"abt9-client\">Ravi Poojary</h3>\r\n                            <div class=\"abt9-client-role\">Home Owner</div>\r\n                        </div>\r\n\r\n                        <div class=\"abt9-client-mark\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                        </div>\r\n                    </div>\r\n\r\n                </article>\r\n\r\n\r\n                <article class=\"abt9-card\">\r\n\r\n                    <div class=\"abt9-quote\">\r\n                        <i class=\"fa-solid fa-quote-left\"></i>\r\n                    </div>\r\n\r\n                    <div class=\"abt9-stars\">\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                    </div>\r\n\r\n                    <p class=\"abt9-review\">\r\n                        It gives me immense pleasure to write this humble review for Arun Bhandary Builders & Developers. The slogan of this Bajpe-based realty enterprise reads \"we build dreams\" ... and so they truly do!<br/>\r\n\r\nThis firm is led by Mr Arun Bhandary, whose knack towards integrating people\'s wishes with bricks, concrete and steel is next to none! Mr Bhandary collaborates with his dynamic team individually and the success stories of his personification are now within the broad public domain.<br/>\r\n\r\nFor quintessential homes of your dreams or any other realty project in your thoughts; think no beyond Arun Builders & Developers ... where the results always exceed expectations!\r\n                    </p>\r\n\r\n                    <div class=\"abt9-card-bottom\">\r\n                        <div>\r\n                            <h3 class=\"abt9-client\">Mahesh Prabhu</h3>\r\n                            <div class=\"abt9-client-role\">Home Owner</div>\r\n                        </div>\r\n\r\n                        <div class=\"abt9-client-mark\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                        </div>\r\n                    </div>\r\n\r\n                </article>\r\n\r\n\r\n                <article class=\"abt9-card\">\r\n\r\n                    <div class=\"abt9-quote\">\r\n                        <i class=\"fa-solid fa-quote-left\"></i>\r\n                    </div>\r\n\r\n                    <div class=\"abt9-stars\">\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                    </div>\r\n\r\n                    <p class=\"abt9-review\">\r\n                       Arun Bhandary Builders & Developers are a trust worthy enterprise. Reliable and hassle free dealings. As I know Mr.Arun for decades as he is very passionate on quality and all his dealings are transparent.<br/>\r\n\r\nA thorough professional with whom we can look forward for our Return Of Investment.\r\n                    </p>\r\n\r\n                    <div class=\"abt9-card-bottom\">\r\n                        <div>\r\n                            <h3 class=\"abt9-client\">Rajnish N</h3>\r\n                            <div class=\"abt9-client-role\">Home Owner</div>\r\n                        </div>\r\n\r\n                        <div class=\"abt9-client-mark\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                        </div>\r\n                    </div>\r\n\r\n                </article>\r\n\r\n\r\n                <article class=\"abt9-card\">\r\n\r\n                    <div class=\"abt9-quote\">\r\n                        <i class=\"fa-solid fa-quote-left\"></i>\r\n                    </div>\r\n\r\n                    <div class=\"abt9-stars\">\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                        <i class=\"fa-solid fa-star\"></i>\r\n                    </div>\r\n\r\n                    <p class=\"abt9-review\">\r\n                        One of the most renowned builders in the city with quality construction, elegant design within budget promised. This company has houses/villas for every kind of requirements with various budget options and types of property and location. I personally know Arun for several years, impressed with the service he provides to this society.\r\n                    </p>\r\n\r\n                    <div class=\"abt9-card-bottom\">\r\n                        <div>\r\n                            <h3 class=\"abt9-client\">Roshan Britto</h3>\r\n                            <div class=\"abt9-client-role\">Home Owner</div>\r\n                        </div>\r\n\r\n                        <div class=\"abt9-client-mark\">\r\n                            <i class=\"fa-solid fa-house\"></i>\r\n                        <